   \"ssh2\": \"^1.16.0\",\n    \"zod\": \"^4.4.3\"\n  },\n  \"engines\": {\n    \"dsh\": \">=0.1.5-alpha.1\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-credentials\": \">=0.1.5-alpha.1\",\n    \"@deepseek-ai/dsh-storage-domain\": \">=0.1.5-alpha.1\",\n    \"@deepseek-ai/dsh-tools\": \">=0.1.5-alpha.1\",\n    \"@deepseek-ai/dsh-typert-protocol\": \">=0.1.5-alpha.1\"\n  },\n  \"peerDependenciesMeta\": {},\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.2\",\n    \"@deepseek-ai/dsh-credentials\": \"0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-storage-domain\": \"0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"0.1.2-rc.1\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"0.1.2-rc.1\",\n    \"@eslint/js\": \"^10.0.1\",\n    \"@xterm/addon-fit\": \"0.10.0\",\n    \"@xterm/addon-search\": \"0.15.0\",\n    \"@xterm/xterm\": \"5.5.0\",\n    \"mongodb\": \"^6.10.0\",\n    \"esbuild\": \"^0.24.2\",\n    \"eslint\": \"^10.10.0\",\n    \"globals\": \"^17.12.0\",\n    \"react\": \"^18.3.1\"\n  },\n  \"scripts\": {\n    \"gen:xterm-css\": \"node scripts/gen-xterm-css.mjs\",\n    \"build:host\": \"node scripts/build-host.mjs\",\n    \"build:client\": \"node scripts/build-client.mjs\",\n    \"build\": \"npm run gen:xterm-css && npm run build:host && npm run build:client\",\n    \"prepare\": \"npm run build\",\n    \"lint\": \"eslint .\",\n    \"bump:readme\": \"node scripts/bump-readme.mjs\",\n    \"test\": \"node --test test/safety.mjs test/db-safety.mjs test/trash.mjs test/db-guard.mjs test/db-ops.mjs test/db-hang.mjs test/db-keepalive.mjs test/db-charset.mjs test/db-query-timeout.mjs test/ssh-auth.mjs test/ssh-agent.mjs test/dual-factor.mjs test/sftp-dir.mjs test/ssh-legacy-kex.mjs test/ssh-banner.mjs test/hostkey.mjs test/batch.mjs test/scp.mjs test/command-snippets.mjs test/ssh-panel-command-picker.mjs test/client.mjs test/client-apply-reentrancy.mjs test/manifest.mjs test/release-packaging.mjs test/ssh-write.mjs test/credentials.mjs test/sftp-tools.mjs test/stream-file-routes.mjs test/manual-terminal-context.mjs test/terminal-stream.mjs test/exec-cwd.mjs test/exec-cwd-rules.mjs test/login-command.mjs test/tunnel-crash.mjs test/network-cli.mjs test/terminal-pool.mjs test/terminal-theme.mjs test/pane-selection.mjs test/profile-connection.mjs test/active-connection.mjs test/agent-connect.mjs test/agent-connection-poll.mjs test/sidebar-integration.mjs test/settings-nav-icon.mjs test/sidebar-lifecycle.mjs test/review-regressions.mjs test/project-directory.mjs test/remote-workspace.mjs test/remote-workspace-service.mjs test/remote-workspace-ui.mjs test/domain-records.mjs test/db-lazy-load.mjs test/db-extra-drivers.mjs test/typert-sync.mjs test/sftp-files-ui.mjs test/remote-file-search.mjs test/socks5.mjs test/session-log.mjs test/terminal-text.mjs test/terminal-search.mjs test/shell-integration.mjs test/local-sshd-sftp.mjs test/resource-group-collapse.mjs test/resource-card-layout.mjs test/i18n.mjs test/exec-policy.mjs test/update-guidance.mjs test/ssh-read-incremental.mjs test/terminal-zoom.mjs test/log-highlight.mjs test/ask-gate.mjs\",\n    \"install:dev\": \"node scripts/install-dev.mjs\",\n    \"pack:release\": \"npm run build && node scripts/package-release.mjs\",\n    \"i18n:extract\": \"node scripts/i18n-extract.mjs\"\n  }\n}\n"
