`transaction ${txId} not found or already finished`);\n    const label = action === \"COMMIT\" ? \"db_tx_commit\" : \"db_tx_rollback\";\n    // The connection's connect-time override (if any) travels on the handle.\n    const opBudget = tx.handle.opTimeoutMs ?? this.dl(\"op\");\n    let killed = false;\n    try {\n      const settled = tx.handle.kind === \"mysql\"\n        ? await raceDeadline(tx.handle.conn.query(action), {\n          signal, timeoutMs: opBudget, label, onLose: () => { killed = true; }\n        })\n        : await raceDeadline(tx.handle.client.query(action), {\n          signal, timeoutMs: opBudget, label, onLose: () => { killed = true; }\n        });\n      void settled;\n      if (killed) {\n        // Raced out: the connection is mid-protocol and its transaction state\n        // is unknown, so drop it instead of returning it to the pool.\n        if (tx.handle.kind === \"mysql\") tx.handle.conn.destroy();\n        else tx.handle.client.release(new Error(`${label}: connection killed after timeout`));\n        this.dbTransactions.delete(txId);\n        if (tx.timer) clearTimeout(tx.timer);\n        return fail(errorCode, `${label} timed out after ${opBudget}ms: the transaction outcome is unknown — verify the data before retrying`);\n      }\n      if (tx.handle.kind === \"mysql\") tx.handle.conn.release();\n      else tx.handle.client.release();\n      if (tx.timer) clearTimeout(tx.timer);\n      this.dbTransactions.delete(txId);\n      const value = { txId, finished: true };\n      value[action === \"COMMIT\" ? \"committed\" : \"rolledBack\"] = true;\n      return { ok: true, value };\n    } catch (error) {\n      this.dbTransactions.delete(txId);\n      if (tx.timer) clearTimeout(tx.timer);\n      try {\n        if (tx.handle.kind === \"mysql\") tx.handle.conn.destroy();\n        else tx.handle.client.release(killed ? new Error(`${label}: connection killed after cancel/timeout`) : undefined);\n      } catch {}\n      return fail(errorCode, error.message);\n    }\n  }\n\n  /** Timer/transport-driven cleanup: rolls back and releases the connection. */\n  async disposeTransaction(txId, action) {\n    const tx = this.dbTransactions.get(txId);\n    if (!tx) return;\n    this.dbTransactions.delete(txId);\n    if (tx.timer) clearTimeout(tx.timer);\n    let killed = false;\n    try {\n      if (tx.handle.kind === \"mysql\") {\n        await raceDeadline(tx.handle.conn.query(action), {\n          timeoutMs: this.dl(\"end\"), label: \"transaction cleanup\", onLose: () => { killed = true; }\n        });\n        if (killed) tx.handle.conn.destroy();\n        else tx.handle.conn.release();\n      } else {\n        await raceDeadline(tx.handle.client.query(action), {\n          timeoutMs: this.dl(\"end\"), label: \"transaction cleanup\", onLose: () => { killed = true; }\n        });\n        if (killed) tx.handle.client.release(new Error(\"transaction cleanup: connection killed after timeout\"));\n        else tx.handle.client.release();\n      }\n    } catch {\n      try { if (tx.handle.kind === \"mysql\") tx.handle.conn.destroy(); else tx.handle.client.release(); } catch {}\n    }\n  }\n\n  /** Roll back every transaction of a connection (used by explicit disconnect). */\n  async disposeDbTransactionsFor(dbConnectionId) {\n    const ids = [...this.dbTransactions.keys()].filter((id) => this.dbTransactions.get(id)?.dbId === dbConnectionId);\n    for (const id of ids) {\n      await this.disposeTransaction(id, \"ROLLBACK\").catch(() => {});\n    }\n  }\n\n  /** Drop transaction bookkeeping without touching the (already dead) pool. */\n  dropTransactionsFor(dbConnectionId) {\n    if (!this.dbTransactions) return; // partially-constructed instances in unit tests\n    for (const [txId, tx] of [...this.dbTransactions.entries()]) {\n      if (tx.dbId === dbConnectionId) {\n        if (tx.timer) clearTimeout(tx.timer);\n        this.dbTransactions.delete(txId);\n      }\n    }\n  }\n\n  /**\n   * Transport-loss counterpart of disposeDbTransactionsFor: per open\n   * transaction, attempt a bounded ROLLBACK (the wire may still be half-alive)\n   * and always end with destroy/release-with-error so the dedicated pooled\n   * connection is reclaimed even when the transport is gone. Fire-and-forget —\n   * the loss handler must not wait on a dead transport.\n   */\n  abandonTransactionsFor(dbConnectionId) {\n    if (!this.dbTransactions) return; // partially-constructed instances in unit tests\n    for (const [txId, tx] of [...this.dbTransactions.entries()]) {\n      if (tx.dbId !== dbConnectionId) continue;\n      if (tx.timer) clearTimeout(tx.timer);\n      // disposeTransaction drops the bookmark itself once it has settled.\n      void this.disposeTransaction(txId, \"ROLLBACK\").catch(() => {});\n    }\n  }\n\n  // ── performance diagnostics ─────────────────────────────────────────────────\n\n  /**\n   * EXPLAIN a caller-supplied SELECT/WITH query. The statement is gated by the\n   * read-only lexer first; the EXPLAIN prefix is prepended as a plain string\n   * (the only permitted leading verbs make it impossible to smuggle a write\n   * past the gate) and values stay bound as driver placeholders.\n   */\n  async explain(request) {\n    let record;\n    try { record = this.getRecord(request.dbConnectionId); }\n    catch (error) { return fail(\"no-db-connection\", error.message); }\n    if (!isSqlType(record.type)) {\n      return fail(\"unsupported-op\", `db_explain only supports SQL databases (mysql/postgresql/opengauss/sqlite/clickhouse)`);\n    }\n    const gate = assessReadOnlySql(request.sql);\n    if (!gate.ok) return fail(\"readonly-sql\", gate.reason);\n    if (!gate.verbs?.length || ![\"SELECT\", \"WITH\"].includes(gate.verbs[0])) {\n      return fail(\"unsupported-op\", t(\"db_explain 仅支持 SELECT/WITH 查询计划\"));\n    }\n    const opts = { signal: request.signal, label: \"db_explain\" };\n    try {\n      let plan;\n      if (record.type === \"mysql\") {\n        const [r] = await this.mysqlQueryOnce(record, \"EXPLAIN FORMAT=JSON \" + request.sql, request.params ?? [], opts);\n        const raw = r?.[0]?.EXPLAIN ?? null;\n        plan = typeof raw === \"string\" ? JSON.parse(raw) : raw;\n      } else if (record.type === \"sqlite\") {\n        // SQLite prints the plan as rows; the array is the plan.\n        plan = sqliteQuery(record.client, \"EXPLAIN QUERY PLAN \" + request.sql, request.params ?? [], this.maxDbRows).rows;\n      } else if (record.type === \"clickhouse\") {\n        // ClickHouse's EXPLAIN has no cross-version JSON default: ask for JSON\n        // first and fall back to the textual plan when the server rejects it.\n        const json = await clickhouseQuery(record, \"EXPLAIN json = 1 \" + request.sql, request.params ?? [], {\n          signal: opts.signal, fetchImpl: this.fetchImpl, maxRows: 50\n        }).catch(() => null);\n        const raw = json?.rows?.[0]?.explain ?? null;\n        plan = raw === null || raw === undefined\n          ? (await clickhouseQuery(record, \"EXPLAIN \" + request.sql, request.params ?? [], {\n              signal: opts.signal, fetchImpl: this.fetchImpl, maxRows: 200\n            })).rows\n          : (typeof raw === \"string\" ? JSON.parse(raw) : raw);\n      } else {\n        const r = await this.pgQueryOnce(record, \"EXPLAIN (FORMAT JSON) \" + request.sql, request.params ?? [], opts);\n        const raw = r.rows?.[0]?.[\"QUERY PLAN\"] ?? null;\n        plan = typeof raw === \"string\" ? JSON.parse(raw) : raw;\n      }\n      return { ok: true, value: { plan: serializeDbValue(plan) } };\n    } catch (error) {\n      return fail(\"db-explain-failed\", error.message);\n    }\n  }\n\n  async run(request) {\n    let record;\n    try { record = this.getRecord(request.dbConnectionId); }\n    catch (error) { return fail(\"no-db-connection\", error.message); }\n    try {\n      if (record.type === \"redis\") {\n        const { command, args } = request;\n        if (!command) return fail(\"bad-request\", \"redis run requires { command, args }\");\n        // node-redis queues commands while the socket is down and would answer\n        // only after its own reconnect succeeds — on a dead tunnel that never\n        // happens, so the command must race client-side. A lost race leaves the\n        // connection suspect: drop it (disconnect also stops the retry loop).\n        const result = await raceDeadline(record.client.sendCommand([command, ...(args ?? [])]), {\n          signal: request.signal, timeoutMs: this.opDeadlineFor(record), label: \"db_run\",\n          onLose: (error) => { this.handleDbTransportLoss(record.id, record.client, error); }\n        });\n        return { ok: true, value: { result: serializeDbValue(result) } };\n      }\n      if (record.type === \"mongodb\") {\n        const { collection, operation, filter, document, update, options } = request;\n        if (!collection || !operation) return fail(\"bad-request\", \"mongodb run requires { collection, operation }\");\n        const col = record.client.db(record.config.database).collection(collection);\n        // The driver's own socketTimeoutMS is a SERVER option; a locally dead\n        // tunnel is not covered by it, so every op races the client deadline.\n        const mongoRun = async () => {\n          switch (operation) {\n            case \"find\": return await col.find(filter ?? {}).limit(100).toArray();\n            case \"findOne\": return await col.findOne(filter ?? {});\n            case \"insertOne\": return await col.insertOne(document);\n            case \"updateOne\": return await col.updateOne(filter ?? {}, update, options);\n            case \"deleteOne\": return await col.deleteOne(filter ?? {});\n            case \"countDocuments\": return await col.countDocuments(filter ?? {});\n            default: throw new Error(`unsupported mongo operation: ${operation}`);\n          }\n        };\n        const result = await raceDeadline(mongoRun(), {\n          signal: request.signal, timeoutMs: this.opDeadlineFor(record), label: \"db_run\",\n          onLose: (error) => {\n            // Clear the stuck topology so the next call starts from a clean\n            // selection instead of queueing behind the dead one.\n            try { record.client.close(true).catch(() => {}); } catch {}\n            this.handleDbTransportLoss(record.id, record.client, error);\n          }\n        });\n        return { ok: true, value: { result: serializeDbValue(result) } };\n      }\n      return fail(\"unsupported-op\", `db_run only supports redis/mongodb, use db_query for ${record.type}`);\n    } catch (error) {\n      return fail(\"db-run-failed\", error.message);\n    }\n  }\n}\n"
    },
    {
      "path": "src/hostkey.js",
      "content": "/**\n * Host-key fingerprint TOFU helpers for dsh-ssh-ops.\n *\n * Pure, side-effect-free functions split out of the connect path so the\n * ssh2 `hostVerifier` contract (raw host-key blob Buffer since ssh2 v1.17)\n * and the accept-new / verify / off decision matrix are unit-tested against\n * the REAL wire shape — a mock object must never hide a contract drift.\n *\n * The KnownHosts wrapper adapts a dsh-storage-domain table\n * (get/put/delete/entries) to host+port addressing so the connect path speaks\n * in servers, not in opaque storage keys.\n */\nimport { createHash } from \"node:crypto\";\n\n/** Host-key verification modes, in the order used by the UI selector. */\nexport const HOST_KEY_MODES = [\"accept-new\", \"verify\", \"off\"];\n\nexport const DEFAULT_HOST_KEY_MODE = \"accept-new\";\n\n/**\n * Extract the SSH host-key algorithm name from a raw host-key blob\n * (SSH wire format: `uint32 len` + algorithm string + key data).\n */\nexport function blobAlgorithm(blob) {\n  if (!Buffer.isBuffer(blob) || blob.length < 4) return \"\";\n  try {\n    const len = blob.readUInt32BE(0);\n    return blob.toString(\"utf8\", 4, 4 + len);\n  } catch {\n    return \"\";\n  }\n}\n\n/**\n * SHA-256 fingerprint (base64, without the `SHA256:` prefix) of an ssh2\n * host-key blob. ssh2 v1.17 `hostVerifier` receives the RAW host-key blob\n * Buffer (the SSH wire-format `string(algo) string(keydata)`); defensively\n * also accept the legacy `{ hash }` object shape.\n */\nexport function keyFingerprint(key) {\n  const blob = Buffer.isBuffer(key) ? key : (key && key.hash);\n  if (!blob) throw new Error(\"host key missing (hostVerifier received no key blob)\");\n  return createHash(\"sha256\").update(blob).digest(\"base64\");\n}\n\n/** Build a wire-shaped host-key blob for tests: `string(algo) + string(32 bytes)`. */\nexport function makeKeyBlob(algo, seed) {\n  const algoBuf = Buffer.from(algo, \"utf8\");\n  const data = Buffer.alloc(32, seed || 1);\n  const blob = Buffer.alloc(4 + algoBuf.length + 4 + data.length);\n  blob.writeUInt32BE(algoBuf.length, 0);\n  algoBuf.copy(blob, 4);\n  blob.writeUInt32BE(data.length, 4 + algoBuf.length);\n  data.copy(blob, 8 + algoBuf.length);\n  return blob;\n}\n\n/** Storage key for a host:port pair (the unit known_hosts is addressed by). */\nexport function knownHostKey(host, port) {\n  return `${host}:${port ?? 22}`;\n}\n\n/**\n * Pure verdict for a host-key check, decoupled from ssh2 so it is unit-testable.\n *\n * @param {object} args\n * @param {\"accept-new\"|\"verify\"|\"off\"} args.mode\n * @param {object|undefined} args.known   stored record ({ fingerprint } or undefined)\n * @param {string} args.presentedFingerprint  fingerprint of the key the server presented\n * @param {string} [args.algorithm]          algorithm name (persisted on first-seen)\n * @returns {{accept: boolean, reason?: string, record?: {fingerprint, algorithm}, expected?: string, got?: string}}\n */\nexport function decideHostKey({ mode, known, presentedFingerprint, algorithm }) {\n  if (mode === \"off\") return { accept: true };\n\n  if (mode === \"verify\") {\n    if (!known) return { accept: false, reason: \"unseen-host\" };\n    if (known.fingerprint !== presentedFingerprint) {\n      return { accept: false, reason: \"host-key-mismatch\", expected: known.fingerprint, got: presentedFingerprint };\n    }\n    return { accept: true };\n  }\n\n  // accept-new (default): trust on first use, reject on change.\n  if (!known) return { accept: true, record: { fingerprint: presentedFingerprint, algorithm } };\n  if (known.fingerprint !== presentedFingerprint) {\n    return { accept: false, reason: \"host-key-mismatch\", expected: known.fingerprint, got: presentedFingerprint };\n  }\n  return { accept: true };\n}\n\n/**\n * Adapter over a dsh-storage-domain table (get/put/delete/entries) that\n * addresses known hosts by host:port. Pure delegation — no caching, so the\n * table remains the single source of truth and reconnects see fresh state.\n */\nexport class KnownHosts {\n  constructor(table) {\n    this.table = table;\n  }\n\n  get(host, port) {\n    return this.table.get(knownHostKey(host, port));\n  }\n\n  async record(host, port, { fingerprint, algorithm }) {\n    const key = knownHostKey(host, port);\n    const now = new Date().toISOString();\n    const previous = this.table.get(key);\n    await this.table.put(key, {\n      host,\n      port: port ?? 22,\n      algorithm,\n      fingerprint,\n      firstSeenAt: previous?.firstSeenAt ?? now,\n      lastSeenAt: now\n    });\n  }\n\n  forget(host, port) {\n    return this.table.delete(knownHostKey(host, port));\n  }\n\n  list() {\n    return [...this.table.entries()].map(([key, value]) => ({ key, ...value }));\n  }\n}\n"
    },
    {
      "path": "src/index.js",
      "content": "/**\n * dsh-ssh-ops host half: a Typert Remote service named `sshOps` that manages\n * ssh2 connections and PTY shell sessions, streaming output to the browser\n * through long-poll reads. Also registers agent tools (ssh_connect, ssh_exec,\n * ...) so the main conversation can drive the same sessions the panel shows.\n */\nimport { createTerminalOutput } from \"./terminal-output.js\";\nimport { extractCliPrompt, promptReturned, cliPageRequested, stripCliOutput, sanitizeCliCommand } from \"./network-cli.js\";\nimport { randomUUID } from \"node:crypto\";\nimport { findReusableProfileConnection } from \"./profile-connection.js\";\nimport { resolveProfileRef, noConnectionGuidance, AUTO_CONNECT_DISABLED_MESSAGE } from \"./agent-connect.js\";\nimport net from \"node:net\";\nimport { Client } from \"ssh2\";\nimport { Service } from \"@deepseek-ai/cordis\";\nimport { credentialRef } from \"@deepseek-ai/dsh-credentials\";\nimport { defineDomain, domainTable } from \"@deepseek-ai/dsh-storage-domain\";\nimport { TypertRemoteService } from \"@deepseek-ai/dsh-typert-protocol\";\nimport { z } from \"zod\";\nimport { assessShellCommand, normalizeAllowList, normalizePolicy, shellQuote, CATEGORY_DELETE_FILES, ALL_CATEGORY_KEYS, CATEGORY_LABELS } from \"./safety.js\";\nimport { EXEC_CWD_ERROR_PREFIX, buildCwdAwareCommand, execEchoWarning, extractExecCwd, posixLoginShell } from \"./exec-cwd.js\";\nimport { buildTrashCommand, parseSimpleDeleteCommand, parseTrashOutput } from \"./trash.js\";\nimport { scpCommand, scpDownload, scpUpload } from \"./scp.js\";\nimport { redactForModel } from \"./redact.js\";\nimport { isTransientConnectError } from \"./net-errors.js\";\nimport { isIdentMismatchError, withRepairedBanner } from \"./ssh-banner.js\";\nimport { createAuthTracker, makeAuthHandler, classifyConnectFailure, formatConnectFailure, wasAuthCut } from \"./ssh-auth.js\";\nimport { applyAgentForwarding } from \"./ssh-agent.js\";\nimport { processTerminalInput } from \"./terminal-input.js\";\nimport { fail } from \"./envelope.js\";\nimport { POLICY_NOTICE_PREFIX } from \"./policy-messages.js\";\nimport { DbOpsManager } from \"./db-ops.js\";\nimport { defaultDbPort } from \"./db-drivers.js\";\nimport { attachSocks5 } from \"./socks5.js\";\nimport { SessionLogStore } from \"./session-log.js\";\nimport { SHELL_FAMILY_PROBE, ShellIntegrationTracker, parseShellFamilyProbe, shellIntegrationCommand } from \"./shell-integration.js\";\nimport { homedir } from \"node:os\";\nimport { join as joinPath, dirname as dirnamePath, relative as relativePath, posix } from \"node:path\";\nimport { mkdir as fsMkdir, readdir as fsReaddir, stat as fsStat, unlink as fsUnlink } from \"node:fs/promises\";\nimport { createReadStream, createWriteStream } from \"node:fs\";\nimport { pipeline as streamPipeline } from \"node:stream/promises\";\nimport { runTransferTasks, joinRemotePath, splitRemotePath } from \"./sftp-dir.js\";\nimport {\n  KnownHosts,\n  decideHostKey,\n  keyFingerprint,\n  blobAlgorithm,\n  DEFAULT_HOST_KEY_MODE\n} from \"./hostkey.js\";\nimport {\n  RemoteWorkspaceStore,\n  RemoteWorkspacePathError,\n  remoteWorkspaceDomainSpec,\n  remoteWorkspacePromptText,\n  normalizeRemoteRoot,\n  resolveRemotePath,\n  isRemotePathInside,\n  workspaceRelativePart,\n  REMOTE_WORKSPACE_OFFLINE,\n  REMOTE_WORKSPACE_OUTSIDE\n} from \"./remote-workspace.js\";\nimport { registerSshSessionTools } from \"./tools/ssh-session.js\";\nimport { registerSftpTools } from \"./tools/sftp.js\";\nimport { registerTunnelTools } from \"./tools/tunnel.js\";\nimport { registerBatchTools } from \"./tools/batch.js\";\nimport { registerDbTools } from \"./tools/db.js\";\nimport { registerSessionLogTools } from \"./tools/session-log.js\";\nimport { t, setLanguage } from \"./i18n/core.js\";\n\nconst MAX_BUFFER_BYTES = 2 * 1024 * 1024;\nconst MAX_COMMAND_OUTPUT_BYTES = 64 * 1024;\nconst MAX_CAPTURE_BYTES = 128 * 1024;\nconst READ_TIMEOUT_MS = 300;\nconst MAX_SESSIONS = 64;\nconst OPERATOR_APPROVAL_TTL_MS = 5 * 60 * 1000;\nconst SFTP_DIR_FILE_IDLE_TIMEOUT_MS = 60 * 1000;\n// ssh2 disables keepalives by default; without them NATs and cloud firewalls\n// silently drop idle connections and every later operation fails on a dead\n// transport. Keep the mapping alive and detect a truly dead link fast.\nconst KEEPALIVE_INTERVAL_MS = 20000;\nconst KEEPALIVE_COUNT_MAX = 3;\n// Transient connect failures (resets, timeouts, scanner-induced refusals) are\n// retried with backoff; authentication failures are never retried.\nconst CONNECT_RETRIES = 3;\n\n/**\n * Key-exchange algorithms for Huawei legacy VRP (S12712 and similar switches,\n * also some old IOS/Comware builds). Such devices offer ONLY SHA-1 group14 and\n * reject every modern KEX, so the handshake dies with \"no matching key\n * exchange algorithm\" and the device looks simply unreachable.\n *\n * ssh2 ships `diffie-hellman-group14-sha1` in SUPPORTED_KEX but deliberately\n * leaves it out of DEFAULT_KEX (SHA-1 KEX is no longer considered secure), so\n * it must be opted into explicitly. `append` places these after every modern\n * algorithm: a modern peer still negotiates modern, and only a peer that\n * speaks nothing else lands on SHA-1. Scope is deliberately KEX-only — host\n * key and cipher policy are left at ssh2's defaults.\n */\nexport const LEGACY_VRP_ALGORITHMS = Object.freeze({\n  kex: { append: [\"diffie-hellman-group14-sha1\"] }\n});\n\n/**\n * True when the handshake failed because the two sides share no KEX algorithm\n * (as opposed to a wrong password, an unreachable host, or a timeout). Only\n * this specific failure justifies retrying with legacy algorithms — matching\n * anything broader would silently weaken every failing connection.\n */\nexport function isKexMismatchError(error) {\n  const message = String(error?.message ?? error ?? \"\");\n  return /no matching key exchange|no matching kex|key exchange algorithm/i.test(message);\n}\nconst RECONNECT_BASE_DELAY_MS = 1000;\nconst RECONNECT_MAX_DELAY_MS = 30000;\nconst RECONNECT_WAIT_MS = 30000;\n// Stream push keepalive: when the terminal is idle the generator still yields\n// an empty item at this cadence, so the client can tell a live-but-quiet\n// terminal from a dead WebSocket mux.\nconst STREAM_HEARTBEAT_MS = 15000;\n// Streaming file plane (workbench S6 patch): plain-HTTP byte routes registered\n// on the DSH webserver, guarded by the connection service's Host/Origin +\n// browser-cookie fence (the same guard the typert gateway applies to /api and\n// /api/remote.mux). Raw bytes on the wire — no base64 envelope, and no\n// whole-file buffering on either side of the ssh2 SFTP streams.\nconst STREAM_ROUTE_PREFIX = \"/ssh-ops/stream\";\nconst STREAM_HIGH_WATER_MARK = 256 * 1024;\n// Zombie-upload bound: a paused request cannot observe the client's FIN while\n// unread body bytes precede it (Node reports request close only after the body\n// drains), so an idle-socket timeout backstops the cancelled-upload cleanup.\nconst STREAM_IDLE_TIMEOUT_MS = 30000;\n// batchRun opens a full SSH connect + exec per target; an unbounded Promise.all\n// would storm every selected server (and any rate-limited network path between)\n// at once. Worker-pool the targets instead.\nconst BATCH_MAX_CONCURRENCY = 4;\n// Upper bound for one SFTP/SCP read (agent tools may lower it via max_bytes).\nconst MAX_FILE_READ_BYTES = 4 * 1024 * 1024;\n// Late readers can still see the exit status of the N most recently exited\n// sessions (session tombstones).\nconst MAX_EXIT_TOMBSTONES = 64;\nconst DEFAULT_DB_ROWS = 200;\nconst HARD_MAX_DB_ROWS = 5000;\n\nfunction parseDbRows(raw = process.env.DSH_SSH_OPS_MAX_DB_ROWS) {\n  if (raw === undefined) return DEFAULT_DB_ROWS;\n  if (!/^[1-9][0-9]*$/.test(raw)) throw new Error(\"DSH_SSH_OPS_MAX_DB_ROWS must be a positive integer <= 5000\");\n  const value = Number(raw);\n  if (!Number.isSafeInteger(value) || value > HARD_MAX_DB_ROWS) throw new Error(\"DSH_SSH_OPS_MAX_DB_ROWS must be a positive integer <= 5000\");\n  return value;\n}\n\nfunction parseDbToolRegistration(raw = process.env.DSH_SSH_OPS_REGISTER_DB_TOOLS) {\n  if (raw === undefined || raw === \"1\" || raw?.toLowerCase() === \"true\") return true;\n  if (raw === \"0\" || raw?.toLowerCase() === \"false\") return false;\n  throw new Error(\"DSH_SSH_OPS_REGISTER_DB_TOOLS must be 0, 1, true, or false\");\n}\n\nconst profileRecordSchema = z.object({\n  name: z.string(),\n  host: z.string(),\n  port: z.number().int(),\n  username: z.string(),\n  authKind: z.enum([\"password\", \"key\"]),\n  groupId: z.string().uuid().nullable(),\n  // Host-key TOFU mode persisted per saved server; optional so records saved\n  // before this feature existed still load (treated as the accept-new default).\n  hostKeyMode: z.string().optional(),\n  // Optional shared credential and jump chain.  Both are optional so the\n  // domain can read every pre-0.3.3 resource without migration.\n  credentialId: z.string().uuid().nullable().optional(),\n  // Optional so already-saved resources load without a storage migration.\n  // Nullable because profileSave persists `null` for \"no project directory\"\n  // (the request schema accepts an explicit null to clear the entry) and DSH\n  // re-validates every stored record when it reopens the domain at boot.\n  // This is metadata only; it never contains credentials or shell syntax.\n  defaultProjectPath: z.string().nullable().optional(),\n  // Optional so pre-0.3.x resources load without a migration. Unlike\n  // defaultProjectPath this IS shell syntax: it replaces the login shell of\n  // terminal sessions (exec + pty) and runs with the resource's own authority,\n  // so it is operator-authored config, never agent-writable mid-session.\n  loginCommand: z.string().nullable().optional(),\n  // Resource-level execution policy tier; null/absent follows the global\n  // setting. Only the tier lives here — the custom tier's released-category\n  // set is one operator-maintained global list.\n  execPolicy: z.string().nullable().optional(),\n  proxyJump: z.array(z.union([z.object({ profileId: z.string().uuid() }), z.object({\n    host: z.string(), port: z.number().int(), username: z.string(),\n    authKind: z.enum([\"credential\", \"password\", \"key\"]).optional(), credentialId: z.string().uuid().optional(), hostKeyMode: z.string().optional()\n  })])).optional(),\n  createdAt: z.string(),\n  updatedAt: z.string()\n});\n\nconst credentialRecordSchema = z.object({\n  name: z.string(),\n  authKind: z.enum([\"password\", \"key\"]),\n  createdAt: z.string(),\n  updatedAt: z.string()\n});\n\nconst groupRecordSchema = z.object({\n  name: z.string(),\n  createdAt: z.string(),\n  updatedAt: z.string()\n});\n\n// Exported (with the credential, DB-profile and known-host specs below) so\n// tests can assert that the records each save path writes satisfy the schemas\n// DSH re-validates when it reopens the domain at boot.\nexport const profileDomainSpec = defineDomain({\n  name: \"ssh_ops_profiles\",\n  version: 1,\n  tables: {\n    profiles: domainTable(profileRecordSchema),\n    groups: domainTable(groupRecordSchema)\n  }\n});\n\n// Keep shared credentials in a new unit rather than bumping the established\n// profile unit. DSH's JSON storage rejects in-place unit-version changes, and\n// users' existing server profiles must never prevent the host from booting.\nexport const credentialDomainSpec = defineDomain({\n  name: \"ssh_ops_credentials\",\n  version: 1,\n  tables: { credentials: domainTable(credentialRecordSchema) }\n});\n\nconst dbProfileRecordSchema = z.object({\n  name: z.string(),\n  type: z.enum([\"mysql\", \"postgresql\", \"opengauss\", \"sqlite\", \"clickhouse\", \"redis\", \"mongodb\"]),\n  // SQLite records carry their file path in `database` and leave these empty.\n  host: z.string(),\n  port: z.number().int(),\n  database: z.string().nullable(),\n  username: z.string().nullable(),\n  ssl: z.string(),\n  sshProfileId: z.string().uuid().nullable(),\n  // Connect-time statement deadline (0 = unlimited; null/absent = default).\n  // Optional so records written by older builds keep loading.\n  queryTimeoutMs: z.number().int().nullable().optional(),\n  createdAt: z.string(),\n  updatedAt: z.string()\n});\n\nexport const dbProfileDomainSpec = defineDomain({\n  name: \"db_ops_profiles\",\n  version: 1,\n  tables: {\n    profiles: domainTable(dbProfileRecordSchema)\n  }\n});\n\nconst knownHostRecordSchema = z.object({\n  host: z.string(),\n  port: z.number().int(),\n  algorithm: z.string(),\n  fingerprint: z.string(),\n  firstSeenAt: z.string(),\n  lastSeenAt: z.string()\n});\n\nexport const knownHostDomainSpec = defineDomain({\n  name: \"ssh_ops_known_hosts\",\n  version: 1,\n  tables: {\n    known_hosts: domainTable(knownHostRecordSchema)\n  }\n});\n\n// Operator-level plugin settings (one row, id \"main\"). New fields must be\n// optional so records written by older builds keep loading.\nconst settingsRecordSchema = z.object({\n  agentAutoConnect: z.boolean().optional(),\n  // Interface language chosen by the operator (\"zh\" | \"en\"). Absent means\n  // \"never chosen explicitly\", so the settings page adopts whatever DSH\n  // Settings → Language is showing and writes that back.\n  language: z.enum([\"zh\", \"en\"]).optional(),\n  // When false, the host language is never followed or written back: the\n  // stored `language` value is authoritative. Absent means \"true\" so first\n  // installs behave exactly as before this flag existed.\n  autoApplySystemLanguage: z.boolean().optional(),\n  // Global default execution policy (standard | custom | allowAll) and, for\n  // the custom tier, the released deny-list category keys. Optional so records\n  // written by older builds keep loading; invalid values fall back to the\n  // standard tier at read time, never widen it.\n  execPolicy: z.string().optional(),\n  execPolicyAllow: z.array(z.string()).optional(),\n  // Username the panel prefills into its new-server form; auto-remembered\n  // from the last profileSave (issue #36). Empty/absent falls back to \"root\".\n  defaultUsername: z.string().max(128).optional(),\n  updatedAt: z.string().optional()\n});\n\nexport const settingsDomainSpec = defineDomain({\n  name: \"ssh_ops_settings\",\n  version: 1,\n  tables: {\n    settings: domainTable(settingsRecordSchema)\n  }\n});\n\nconst SETTINGS_ROW_ID = \"main\";\n\n/**\n * The stored default username, hardened: trim, cap the length, collapse\n * blank/absent/non-string to null (\"no preference\").\n */\nexport function normalizeDefaultUsername(value) {\n  if (typeof value !== \"string\") return null;\n  const trimmed = value.trim();\n  return trimmed === \"\" ? null : trimmed.slice(0, 128);\n}\n\n/**\n * Interpret one persisted settings record into the runtime switches. Absent\n * `autoApplySystemLanguage` means \"true\" (follow the host), which is also what\n * a first install must behave like. Extracted so boot and tests share one\n * reading of the record.\n */\nexport function loadSettingsRecord(record = {}) {\n  return {\n    agentAutoConnect: record.agentAutoConnect === true,\n    language: record.language === \"zh\" || record.language === \"en\" ? record.language : null,\n    autoApplySystemLanguage: record.autoApplySystemLanguage !== false,\n    // normalizePolicy hardens the tier (unknown values land on standard) and\n    // normalizeAllowList hardens the checklist (unknown keys dropped). The two\n    // are read independently on purpose: a record whose tier is not \"custom\"\n    // still carries the operator's ticks, so switching tiers back and forth\n    // never empties the checklist.\n    execPolicy: normalizePolicy({ mode: record.execPolicy }).mode,\n    execPolicyAllow: normalizeAllowList(record.execPolicyAllow),\n    defaultUsername: normalizeDefaultUsername(record.defaultUsername)\n  };\n}\n\nfunction profileCredentialRefs(profileId) {\n  const stem = profileId.replaceAll(\"-\", \"\").toUpperCase();\n  return {\n    password: `DSH_SSH_OPS_${stem}_PASSWORD`,\n    privateKey: `DSH_SSH_OPS_${stem}_PRIVATE_KEY`,\n    passphrase: `DSH_SSH_OPS_${stem}_PASSPHRASE`\n  };\n}\n\nfunction sharedCredentialRefs(credentialId) {\n  const stem = credentialId.replaceAll(\"-\", \"\").toUpperCase();\n  return {\n    password: `DSH_SSH_OPS_SHARED_${stem}_PASSWORD`,\n    privateKey: `DSH_SSH_OPS_SHARED_${stem}_PRIVATE_KEY`,\n    passphrase: `DSH_SSH_OPS_SHARED_${stem}_PASSPHRASE`\n  };\n}\n\n/**\n * Assemble the wire `auth` object from a primary factor plus an optional\n * opposite-kind secondary factor (dual-factor devices such as firewalls or\n * switches configured with `AuthenticationMethods password,publickey`, or\n * the reverse, require both factors on the SAME connection). For a password\n * primary the secondary is a key and takes the shared passphrase slot; for a\n * key primary the secondary is a plain password.\n */\nfunction assembleAuth(authKind, primaryValue, { secondaryValue, passphraseValue, secondaryPassphraseValue } = {}) {\n  const primary = authKind === \"password\"\n    ? { kind: \"password\", password: primaryValue }\n    : { kind: \"key\", privateKey: primaryValue, ...(passphraseValue === undefined ? {} : { passphrase: passphraseValue }) };\n  if (secondaryValue === undefined) return primary;\n  const secondary = authKind === \"password\"\n    ? { kind: \"key\", privateKey: secondaryValue, ...(secondaryPassphraseValue === undefined ? {} : { passphrase: secondaryPassphraseValue }) }\n    : { kind: \"password\", password: secondaryValue };\n  return { ...primary, secondary };\n}\n\nfunction profileJumpPasswordRef(profileId, index) {\n  return `DSH_SSH_OPS_${profileId.replaceAll(\"-\", \"\").toUpperCase()}_JUMP_${index}_PASSWORD`;\n}\n\nfunction profileJumpPrivateKeyRef(profileId, index) {\n  return `DSH_SSH_OPS_${profileId.replaceAll(\"-\", \"\").toUpperCase()}_JUMP_${index}_PRIVATE_KEY`;\n}\n\nfunction profileJumpPassphraseRef(profileId, index) {\n  return `DSH_SSH_OPS_${profileId.replaceAll(\"-\", \"\").toUpperCase()}_JUMP_${index}_PASSPHRASE`;\n}\n\nfunction dbProfileCredentialRefs(dbProfileId) {\n  const stem = dbProfileId.replaceAll(\"-\", \"\").toUpperCase();\n  return { password: `DSH_DB_OPS_${stem}_PASSWORD` };\n}\n\n/** Base64-decode a wire payload to a UTF-8 string. */\nfunction decodeData(data) {\n  return Buffer.from(data, \"base64\").toString(\"utf8\");\n}\n\n/** Base64-encode a UTF-8 string for the wire. */\nfunction encodeData(text) {\n  return Buffer.from(text, \"utf8\").toString(\"base64\");\n}\n\nfunction appendCapped(current, next, maxBytes) {\n  const existing = Buffer.byteLength(current, \"utf8\");\n  const incoming = Buffer.from(next, \"utf8\");\n  if (existing >= maxBytes) return { text: current, truncated: incoming.length > 0 };\n  const remaining = maxBytes - existing;\n  if (incoming.length <= remaining) return { text: current + next, truncated: false };\n  return { text: current + incoming.subarray(0, remaining).toString(\"utf8\"), truncated: true };\n}\n\nfunction tailCapped(text, maxBytes) {\n  const bytes = Buffer.from(text, \"utf8\");\n  return bytes.length <= maxBytes ? text : bytes.subarray(bytes.length - maxBytes).toString(\"utf8\");\n}\n\nfunction promptFromTerminalData(text) {\n  const visible = String(text)\n    .replace(/\\x1b\\][^\\x07]*(?:\\x07|\\x1b\\\\)/g, \"\")\n    .replace(/\\x1b\\[[0-?]*[ -/]*[@-~]/g, \"\");\n  const match = visible.match(/(?:^|[\\r\\n])([^\\r\\n]*[#$] )$/);\n  return match?.[1] ?? null;\n}\n\n/**\n * ssh2 exec channels return LF-delimited text. xterm keeps the current column\n * on a bare LF, which makes multi-line agent output drift diagonally. Agent\n * output is synthetic terminal data, so normalize it to the terminal CRLF.\n */\nexport function normalizeTerminalEol(text) {\n  return String(text ?? \"\").replace(/\\r\\n|\\r|\\n/g, \"\\r\\n\");\n}\n\n/**\n * SshOpsService: one cordis service (and Typert Remote) that owns all SSH\n * connections and their PTY shell sessions for the web profile.\n */\nexport default class SshOpsService extends TypertRemoteService {\n  /** Host-owned profiles and secrets never cross the agent tool boundary. */\n  static inject = [\"tools\", \"storageDomain\", \"credentials\"];\n\n  /** connectionId -> live connection record */\n  connections = new Map();\n  /** sessionId -> live PTY shell session record */\n  sessions = new Map();\n  /** sessionId -> tombstoned exit records for late reads */\n  exitedSessions = new Map();\n  /**\n   * callId -> operator approval voucher for one agent-originated dangerous\n   * command. The tools/pre-execute gate asks through the host's approval\n   * channel and records the grant here; the tool body consumes it exactly\n   * once (and only for the same connection/command) to proceed past the\n   * inner safety gate. TTL-bounded so an aborted execution cannot leak a\n   * live grant. This replaced the 0.3.x confirmation-card queue: the ask\n   * suspends the tool call itself, so nothing waits in a panel-side queue\n   * anymore.\n   */\n  operatorApprovals = new Map();\n  /** batchId -> operator-selected batch exec task awaiting selection/execution. */\n  batchTasks = new Map();\n\n  /** The connection currently represented by the right-side terminal panel. */\n  activeConnectionId = null;\n  /**\n   * Agent auto-connect switch (issue #25): when true the agent may connect\n   * saved SSH resources itself (ssh_connect_profile, and ssh_list shows the\n   * saved resources). Persisted in ssh_ops_settings; default OFF.\n   */\n  agentAutoConnect = false;\n  /**\n   * Global default execution policy (\"standard\" | \"custom\" | \"allowAll\") and\n   * the custom tier's released deny-list category keys. Persisted in\n   * ssh_ops_settings; the default keeps the historical behavior where every\n   * destructive pattern is held for the operator. Resource records may\n   * override the tier per server; a session switch (execPolicySet) overrides\n   * both in