      "path": "src/session-log.js",
      "content": "/**\n * Session log store: one append-only file per SSH session plus a JSON sidecar\n * with its metadata, under a plugin-owned directory. Recording is bounded on\n * purpose — a session stops writing past its cap (and says so) instead of\n * filling the disk, and the store prunes the oldest sessions past the total\n * budget.\n *\n * The store is deliberately transport-free: the service feeds it the same text\n * it hands the terminal journal, so a log is exactly what the panel showed.\n */\nimport { createReadStream, createWriteStream } from \"node:fs\";\nimport { mkdir, readFile, readdir, rm, stat, writeFile } from \"node:fs/promises\";\nimport { join } from \"node:path\";\n\n/** Defaults: one session may keep 8 MB, the directory 256 MB. */\nexport const SESSION_LOG_LIMITS = Object.freeze({\n  maxSessionBytes: 8 * 1024 * 1024,\n  maxTotalBytes: 256 * 1024 * 1024,\n  /** Longest prefix of a session that search scans, so one huge log cannot stall the panel. */\n  maxSearchBytes: 32 * 1024 * 1024,\n  maxSearchHits: 200\n});\n\nconst META_SUFFIX = \".json\";\nconst LOG_SUFFIX = \".log\";\n\n/** Filesystem-safe session id (ids are generated internally, but never trust that here). */\nfunction safeId(sessionId) {\n  return String(sessionId).replace(/[^A-Za-z0-9._-]/g, \"_\").slice(0, 96);\n}\n\nexport class SessionLogStore {\n  /**\n   * @param options - `{ dir, limits? }`; the directory is created lazily.\n   */\n  constructor({ dir, limits = {} } = {}) {\n    this.dir = dir;\n    this.limits = { ...SESSION_LOG_LIMITS, ...limits };\n    this.entries = new Map();\n    this.streams = new Map();\n    /** sessionId -> promise settling when the last append reached the file. */\n    this.pending = new Map();\n    this.ready = null;\n  }\n\n  async init() {\n    this.ready ??= mkdir(this.dir, { recursive: true }).catch(() => {});\n    await this.ready;\n  }\n\n  metaPath(sessionId) { return join(this.dir, `${safeId(sessionId)}${META_SUFFIX}`); }\n  logPath(sessionId) { return join(this.dir, `${safeId(sessionId)}${LOG_SUFFIX}`); }\n\n  /** Is this session already being recorded (its entry exists)? */\n  has(sessionId) {\n    return this.entries.has(sessionId);\n  }\n\n  /**\n   * Open a log for one session. The entry exists as soon as this returns\n   * (before the directory or stream is ready), so an append that arrives in\n   * the same tick is buffered rather than dropped — callers that record\n   * lazily call begin() and append() back to back.\n   */\n  async begin({ sessionId, connectionId, name, host, port, openedBy, startedAt = new Date().toISOString() }) {\n    const entry = {\n      sessionId, connectionId: connectionId ?? null, name: name ?? null,\n      host: host ?? null, port: port ?? null, openedBy: openedBy ?? null,\n      startedAt, endedAt: null, exitCode: null, bytes: 0, truncated: false,\n      /** Chunks that arrived before the write stream existed. */\n      pending: []\n    };\n    this.entries.set(sessionId, entry);\n    await this.init();\n    const stream = createWriteStream(this.logPath(sessionId), { flags: \"a\" });\n    stream.on(\"error\", () => { /* a broken log must not crash the session */ });\n    this.streams.set(sessionId, stream);\n    const buffered = entry.pending;\n    entry.pending = [];\n    if (buffered.length > 0) {\n      // Replayed chunks must be covered by flush(): write callbacks fire in\n      // order, so awaiting the LAST one also covers every earlier chunk — and\n      // a read racing begin() sees the data instead of an empty file.\n      this.pending.set(sessionId, new Promise((resolve) => {\n        let done = 0;\n        const onDone = () => { if (++done >= buffered.length) resolve(); };\n        for (const chunk of buffered) {\n          try { stream.write(chunk, onDone); } catch { onDone(); }\n        }\n      }));\n    }\n    await this.writeMeta(entry).catch(() => {});\n    return entry;\n  }\n\n  /** Append session output; past the per-session cap the rest is dropped, once. */\n  append(sessionId, text) {\n    const entry = this.entries.get(sessionId);\n    if (entry === undefined) return;\n    const stream = this.streams.get(sessionId);\n    if (entry.truncated) return;\n    const chunk = String(text ?? \"\");\n    if (chunk.length === 0) return;\n    const remaining = this.limits.maxSessionBytes - entry.bytes;\n    if (remaining <= 0) {\n      entry.truncated = true;\n      return;\n    }\n    const slice = Buffer.byteLength(chunk, \"utf8\") > remaining\n      ? Buffer.from(chunk, \"utf8\").subarray(0, remaining).toString(\"utf8\")\n      : chunk;\n    entry.bytes += Buffer.byteLength(slice, \"utf8\");\n    if (entry.bytes >= this.limits.maxSessionBytes) entry.truncated = true;\n    if (stream === undefined) {\n      // begin() is still preparing the stream: hold the chunk in order.\n      entry.pending.push(slice);\n      return;\n    }\n    try {\n      // Reads await this so a live session's newest output is never missed.\n      this.pending.set(sessionId, new Promise((resolve) => stream.write(slice, resolve)));\n    } catch { /* keep the session alive */ }\n  }\n\n  /** Close one session's log and persist its final metadata. */\n  async end(sessionId, { exitCode = null } = {}) {\n    const entry = this.entries.get(sessionId);\n    const stream = this.streams.get(sessionId);\n    this.streams.delete(sessionId);\n    if (stream !== undefined) {\n      await new Promise((resolve) => stream.end(resolve));\n    }\n    this.pending.delete(sessionId);\n    if (entry === undefined) return null;\n    entry.endedAt = new Date().toISOString();\n    entry.exitCode = exitCode;\n    this.entries.delete(sessionId);\n    await this.writeMeta(entry).catch(() => {});\n    return entry;\n  }\n\n  async writeMeta(entry) {\n    await writeFile(this.metaPath(entry.sessionId), JSON.stringify(entry), \"utf8\");\n  }\n\n  /** All recorded sessions, newest first (metadata only; the log stays a file). */\n  async list() {\n    await this.init();\n    let names;\n    try { names = await readdir(this.dir); } catch { names = []; }\n    const byId = new Map();\n    for (const name of names) {\n      if (!name.endsWith(META_SUFFIX)) continue;\n      try {\n        const meta = JSON.parse(await readFile(join(this.dir, name), \"utf8\"));\n        if (meta?.sessionId === undefined) continue;\n        byId.set(meta.sessionId, {\n          ...meta,\n          startedAt: meta.startedAt ?? null,\n          endedAt: meta.endedAt ?? null,\n          bytes: Number(meta.bytes ?? 0),\n          truncated: meta.truncated === true\n        });\n      } catch {\n        // A half-written sidecar is skipped rather than breaking the list.\n      }\n    }\n    // A session still recording has no fresh sidecar yet (its metadata is only\n    // written at open and close), so the live entry wins and the panel sees\n    // accurate byte counts and truncation while the session runs.\n    for (const [sessionId, live] of this.entries) {\n      const { pending, ...exposed } = live;\n      void pending;\n      byId.set(sessionId, { ...exposed });\n    }\n    return [...byId.values()]\n      .sort((left, right) => String(right.startedAt ?? \"\").localeCompare(String(left.startedAt ?? \"\")));\n  }\n\n  /** Wait for the session's most recent append to hit the file. */\n  async flush(sessionId) {\n    await this.pending.get(sessionId)?.catch(() => {});\n  }\n\n  /** Read a byte range of one log; callers page with `nextOffset`. */\n  async read(sessionId, { offset = 0, maxBytes = 65536 } = {}) {\n    await this.flush(sessionId);\n    await this.init();\n    const path = this.logPath(sessionId);\n    let size;\n    try { size = (await stat(path)).size; } catch { return { ok: false, reason: \"no-such-log\" }; }\n    const start = Math.max(0, Math.min(Number(offset) || 0, size));\n    const length = Math.max(1, Math.min(Number(maxBytes) || 65536, 4 * 1024 * 1024));\n    // An empty or fully-consumed log must not reach createReadStream with\n    // end < start: Node throws ERR_OUT_OF_RANGE synchronously there, escaping\n    // the stream's error event. The empty answer is the correct result anyway.\n    if (start >= size) {\n      return { ok: true, data: \"\", startOffset: start, nextOffset: start, eof: true, size };\n    }\n    const chunks = [];\n    let read = 0;\n    await new Promise((resolve) => {\n      const stream = createReadStream(path, { start, end: Math.min(size, start + length) - 1 });\n      stream.on(\"data\", (chunk) => { chunks.push(chunk); read += chunk.length; });\n      stream.on(\"error\", () => resolve());\n      stream.on(\"end\", resolve);\n    });\n    return {\n      ok: true,\n      data: Buffer.concat(chunks).toString(\"utf8\"),\n      startOffset: start,\n      nextOffset: start + read,\n      eof: start + read >= size,\n      size\n    };\n  }\n\n  /**\n   * Case-insensitive substring search over the first `maxSearchBytes` of a log.\n   * Line-oriented: a hit reports the line (bounded) and the byte offset of the\n   * line's start, so the panel can jump with read().\n   */\n  async search(sessionId, { query, maxHits = this.limits.maxSearchHits } = {}) {\n    const needle = String(query ?? \"\").toLowerCase();\n    if (needle === \"\") return { ok: true, hits: [], scannedBytes: 0, stoppedEarly: false };\n    await this.flush(sessionId);\n    await this.init();\n    const path = this.logPath(sessionId);\n    let size;\n    try { size = (await stat(path)).size; } catch { return { ok: false, reason: \"no-such-log\" }; }\n    const limit = Math.min(size, this.limits.maxSearchBytes);\n    const hits = [];\n    let scanned = 0;\n    let pending = \"\";\n    let pendingOffset = 0;\n    let stoppedEarly = false;\n    await new Promise((resolve) => {\n      const stream = createReadStream(path, { start: 0, end: limit - 1 });\n      stream.on(\"data\", (chunk) => {\n        scanned += chunk.length;\n        pending += chunk.toString(\"utf8\");\n        let index;\n        while ((index = pending.indexOf(\"\\n\")) >= 0) {\n          const line = pending.slice(0, index);\n          if (line.toLowerCase().includes(needle)) {\n            hits.push({ offset: pendingOffset, line: line.slice(0, 500) });\n          }\n          pendingOffset += Buffer.byteLength(pending.slice(0, index + 1), \"utf8\");\n          pending = pending.slice(index + 1);\n          if (hits.length >= maxHits) { stoppedEarly = true; stream.destroy(); resolve(); return; }\n        }\n      });\n      stream.on(\"error\", () => resolve());\n      stream.on(\"close\", resolve);\n      stream.on(\"end\", () => {\n        if (pending !== \"\" && pending.toLowerCase().includes(needle)) {\n          hits.push({ offset: pendingOffset, line: pending.slice(0, 500) });\n        }\n        resolve();\n      });\n    });\n    return { ok: true, hits, scannedBytes: scanned, stoppedEarly };\n  }\n\n  /** Delete one log (and its sidecar). */\n  async remove(sessionId) {\n    this.streams.get(sessionId)?.destroy();\n    this.streams.delete(sessionId);\n    this.entries.delete(sessionId);\n    await rm(this.logPath(sessionId), { force: true }).catch(() => {});\n    await rm(this.metaPath(sessionId), { force: true }).catch(() => {});\n    return { ok: true, deleted: true };\n  }\n\n  /** Delete every recorded session. */\n  async removeAll() {\n    const entries = await this.list();\n    for (const entry of entries) await this.remove(entry.sessionId);\n    return { ok: true, deleted: entries.length };\n  }\n\n  /**\n   * Keep the directory under its total budget by dropping the oldest logs —\n   * the most recent recording is always kept, even if it alone exceeds it.\n   */\n  async prune() {\n    const entries = await this.list();\n    const total = entries.reduce((sum, entry) => sum + (Number(entry.bytes) || 0), 0);\n    let remaining = total;\n    const removed = [];\n    for (const entry of entries.slice(1)) {\n      if (remaining <= this.limits.maxTotalBytes) break;\n      remaining -= Number(entry.bytes) || 0;\n      await this.remove(entry.sessionId);\n      removed.push(entry.sessionId);\n    }\n    return { ok: true, removed, totalBefore: total, totalAfter: Math.max(0, remaining) };\n  }\n}\n"
    },
    {
      "path": "src/tools/db.js",
      "content": "/**\n * Agent tools for database operations (MySQL/PostgreSQL/Redis/MongoDB).\n * Read-only SQL is lexically enforced host-side; destructive statements are\n * returned as copyable cards instead of executed.\n *\n * Every tool declares a cooperative timeoutMs and forwards `exec.signal` down\n * to the driver layer. A half-open transport (SSH tunnel silently dropped: no\n * error event, no data) leaves driver promises that never settle, and the\n * registry cannot hard-kill same-process code — so without a declared budget\n * the dsh timeout policy skips these tools entirely and a hung db_query spins\n * forever, uninterruptible. The budget sits above the db layer's own\n * client-side deadlines so the agent gets the specific message (\"timed out\n * connecting…\", \"…cancelled\") from the layer that knows what hung.\n */\nimport { defineTool } from \"@deepseek-ai/dsh-tools\";\nimport { backupSummary, pickSshConnectionId } from \"../db-ops.js\";\nimport { t } from \"../i18n/core.js\";\n\n/**\n * Cooperative tool-call budget. It must sit above the db layer's own ceilings\n * AND above the largest per-connection query_timeout_ms override\n * (DB_QUERY_TIMEOUT_MAX_MS, 30 min) so an opted-in slow-database connection\n * is never cut off by the tool budget. Default connections are unaffected in\n * practice: every driver await is still bounded by the db layer's own\n * deadlines (the 35s op ceiling fires first), so this budget only matters as\n * the last-resort backstop.\n */\nexport const DB_TOOL_TIMEOUT_MS = 1_860_000;\n\nexport function registerDbTools(ctx, service) {\n  ctx.tools.register(defineTool({\n    name: \"db_connect\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"Connect to a database (MySQL, PostgreSQL, openGauss, SQLite, ClickHouse, Redis, or MongoDB) so the agent can query or run commands in later db_query/db_execute/db_run calls. When an SSH server is connected, a loopback host (127.0.0.1/localhost) is automatically tunneled through the current server (via_ssh=auto), so 'connect to the database on the server' works without an internal connection id; pass via_ssh='no' to force a local connection, or ssh_connection_id to pick a specific server. For cloud-managed databases requiring TLS, set ssl to 'verify' (public-CA certs) or 'preferred' (self-signed certs). Returns a db_connection_id.\",\n    parameters: {\n      type: { type: \"string\", enum: [\"mysql\", \"postgresql\", \"opengauss\", \"sqlite\", \"clickhouse\", \"redis\", \"mongodb\"], required: true, description: \"Database type.\" },\n      host: { type: \"string\", description: \"Database host (required for every type except sqlite). When reached via SSH, this is the address as seen from the SSH server (127.0.0.1 if the DB runs on that server).\" },\n      port: { type: \"integer\", description: \"Database port; defaults per type (3306 MySQL, 5432 PostgreSQL/openGauss, 8123 ClickHouse, 6379 Redis, 27017 MongoDB). Not used by sqlite.\" },\n      database: { type: \"string\", description: \"Database/schema name (MySQL/PostgreSQL/openGauss/ClickHouse, optional), the SQLite file path (required for sqlite), or numeric DB index (Redis).\" },\n      username: { type: \"string\", description: \"Database username (not needed for Redis).\" },\n      password: { type: \"string\", description: \"Database password.\" },\n      ssl: { type: \"string\", enum: [\"disabled\", \"preferred\", \"verify\"], description: \"TLS mode: 'disabled' (default) plain TCP; 'preferred' encrypt without cert verification (self-signed cloud DBs); 'verify' encrypt and verify CA (public-CA cloud DBs).\" },\n      ssh_connection_id: { type: \"string\", description: \"Optional. An existing SSH connection id to tunnel through, reaching databases on private networks. Takes precedence over via_ssh.\" },\n      via_ssh: { type: \"string\", enum: [\"auto\", \"yes\", \"no\"], description: \"Tunnel routing when ssh_connection_id is omitted: 'auto' (default) tunnels loopback hosts (127.0.0.1/localhost) through the current SSH server; 'yes' always tunnels through the current server; 'no' always connects directly.\" },\n      query_timeout_ms: { type: \"integer\", description: \"Optional per-connection statement deadline in milliseconds, set once at connect time for slow databases and large exports: 0 disables the per-statement ceiling (this tool-call budget still applies), 1000..1800000 raises it above the 35s default. Omit for the default.\" },\n      name: { type: \"string\", description: \"Optional display name.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\", additionalProperties: false,\n        properties: {\n          dbConnectionId: { type: \"string\", required: true },\n          name: { type: \"string\", required: true },\n          type: { type: \"string\", required: true }\n        }\n      },\n      render(args, value) {\n        return [{ type: \"text\", text: `Connected ${value.type} ${args.host}:${args.port} (id: ${value.dbConnectionId})` }];\n      }\n    },\n    async execute(args, exec) {\n      const routed = pickSshConnectionId({\n        sshConnectionId: args.ssh_connection_id,\n        viaSsh: args.via_ssh,\n        host: args.host,\n        resolveActive: () => service.resolveConnection(undefined)\n      });\n      if (routed.error) throw new Error(`db_connect failed: ${routed.error.message}`);\n      const result = await service.dbConnect({\n        type: args.type, host: args.host, port: args.port, database: args.database,\n        username: args.username, password: args.password, ssl: args.ssl,\n        sshConnectionId: routed.sshConnectionId, name: args.name, signal: exec?.signal,\n        ...(args.query_timeout_ms !== undefined ? { queryTimeoutMs: args.query_timeout_ms } : {})\n      });\n      if (!result.ok) throw new Error(`db_connect failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"db_list_connections\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"List currently open database connections and their endpoint/account metadata. Use it only when the user asks which databases are connected.\",\n    parameters: {},\n    output: {\n      schema: {\n        type: \"object\", additionalProperties: false,\n        properties: {\n          connections: { type: \"array\", required: true, items: {\n            type: \"object\", additionalProperties: false,\n            properties: {\n              dbConnectionId: { type: \"string\", required: true },\n              name: { type: \"string\", required: true },\n              type: { type: \"string\", required: true },\n              host: { type: \"string\", required: true },\n              port: { type: \"integer\", required: true },\n              database: { oneOf: [{ type: \"string\" }, { type: \"null\" }], required: true },\n              username: { oneOf: [{ type: \"string\" }, { type: \"null\" }], required: true },\n              ssl: { type: \"string\", required: true },\n              sshConnectionId: { oneOf: [{ type: \"string\" }, { type: \"null\" }], required: true },\n              createdAt: { type: \"string\", required: true }\n            }\n          }}\n        }\n      },\n      render(_args, value) {\n        if (!value.connections.length) return [{ type: \"text\", text: \"No database connection is currently open.\" }];\n        const lines = value.connections.map((c) => {\n          const endpoint = c.type === \"sqlite\" ? (c.database ?? \"(no file)\") : `${c.host}:${c.port}`;\n          const metadata = [\n            c.type !== \"sqlite\" && c.database ? `db: ${c.database}` : null,\n            c.username ? `user: ${c.username}` : null,\n            c.ssl && c.ssl !== \"disabled\" ? `TLS: ${c.ssl}` : null,\n            c.sshConnectionId ? \"via SSH\" : null,\n            c.queryTimeoutMs !== undefined ? `query timeout: ${c.queryTimeoutMs === 0 ? \"none\" : `${Math.round(c.queryTimeoutMs / 1000)}s`}` : null\n          ].filter(Boolean);\n          return `- ${c.name} (${c.type}): ${endpoint}${metadata.length ? ` · ${metadata.join(\" · \")}` : \"\"} (id: ${c.dbConnectionId})`;\n        });\n        return [{ type: \"text\", text: lines.join(\"\\n\") }];\n      }\n    },\n    async execute(_args, exec) {\n      const result = await service.dbListConnections({ signal: exec?.signal });\n      if (!result.ok) throw new Error(`db_list_connections failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"db_query\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"Run a read-only SQL query on a connected MySQL or PostgreSQL database and return columns and rows. Read-only is LEXICALLY ENFORCED: only SELECT/SHOW/DESCRIBE/EXPLAIN/WITH(read-only) statements pass; write verbs, SELECT INTO, FOR UPDATE locking reads and data-modifying CTEs are rejected (use db_execute for writes, db_tx_* for verified change workflows). For Redis or MongoDB, use db_run instead. Results stream and are capped at 200 rows; queries time out after 30s.\",\n    parameters: {\n      db_connection_id: { type: \"string\", required: true, description: \"A db_connection_id from db_connect.\" },\n      sql: { type: \"string\", required: true, description: \"SELECT statement. MySQL uses ? placeholders, PostgreSQL uses $1 placeholders.\" },\n      params: { type: \"array\", description: \"Optional parameter values for placeholders.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\", additionalProperties: false,\n        properties: {\n          columns: { type: \"array\", required: true, items: { type: \"string\" } },\n          rows: { type: \"array\", required: true, items: { type: \"object\", additionalProperties: true } },\n          rowCount: { type: \"integer\", required: true },\n          truncated: { type: \"boolean\", required: true }\n        }\n      },\n      render(args, value) {\n        const header = value.columns.join(\"\\t\");\n        const body = value.rows.map((r) => value.columns.map((c) => r[c] ?? \"\").join(\"\\t\")).join(\"\\n\");\n        let text = header.length > 0 ? `${header}\\n${body}` : \"(empty)\";\n        if (value.truncated) text += \"\\n[truncated to 200 rows]\";\n        return [{ type: \"text\", text }];\n      }\n    },\n    async execute(args, exec) {\n      const result = await service.dbQuery({ dbConnectionId: args.db_connection_id, sql: args.sql, params: args.params, signal: exec?.signal });\n      if (!result.ok) throw new Error(`db_query failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"db_execute\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"Run a write SQL statement (INSERT/UPDATE/DELETE/CREATE/ALTER) on a connected MySQL or PostgreSQL database. Destructive statements (DROP/TRUNCATE/SHUTDOWN, detected by leading statement verb so keywords inside string literals or comments are not false-positives) are NOT executed and must never be retried or worked around: DROP TABLE is instead backed up and quarantined by rename (result reports quarantined/renamedTo), while DROP DATABASE/TRUNCATE/SHUTDOWN are blocked after an automatic backup of the affected tables. Only the operator, via the database panel, can finalize any real deletion. For Redis or MongoDB, use db_run instead.\",\n    parameters: {\n      db_connection_id: { type: \"string\", required: true },\n      sql: { type: \"string\", required: true, description: \"Write statement. MySQL uses ? placeholders, PostgreSQL uses $1 placeholders.\" },\n      params: { type: \"array\", description: \"Optional parameter values.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\", additionalProperties: false,\n        properties: {\n          affectedRows: { type: \"integer\", required: true },\n          insertId: { oneOf: [{ type: \"integer\" }, { type: \"string\" }] },\n          truncated: { type: \"boolean\", required: true },\n          blocked: { type: \"boolean\" },\n          reason: { type: \"string\" },\n          sql: { type: \"string\" },\n          quarantined: { type: \"boolean\" },\n          renamedTo: { type: \"string\" },\n          notice: { type: \"string\" },\n          backup: {\n            type: \"array\",\n            items: {\n              type: \"object\",\n              additionalProperties: false,\n              properties: {\n                target: { type: \"string\", required: true },\n                path: { type: \"string\" },\n                schemaPath: { type: \"string\" },\n                bytes: { type: \"integer\" },\n                truncated: { type: \"boolean\" },\n                error: { type: \"string\" }\n              }\n            }\n          }\n        }\n      },\n      render(_args, value) {\n        if (value.quarantined) {\n          const lines = [t(`♻️ DROP 已转换为隔离改名（数据未删除，可随时改回）：${value.sql} → ${value.renamedTo}`)];\n          if (Array.isArray(value.backup) && value.backup.length > 0) {\n            lines.push(backupSummary(value.backup));\n          }\n          lines.push(value.notice ?? t(\"彻底删除请由操作者在数据库面板执行。\"));\n          return [{ type: \"text\", text: lines.join(\"\\n\") }];\n        }\n        if (value.blocked) {\n          const backupNote = Array.isArray(value.backup) && value.backup.length > 0 ? `\\n${backupSummary(value.backup)}` : \"\";\n          return [{ type: \"text\", text: t(`⚠️ 已拦截：${value.reason ?? \"\"}\\nSQL 未执行，请在数据库面板 SQL 编辑器粘贴执行：\\n\\`\\`\\`sql\\n${value.sql ?? \"\"}\\n\\`\\`\\`${backupNote}\\n请勿重试/绕行，由人工执行。`) }];\n        }\n        let text = `Affected ${value.affectedRows} row(s).`;\n        if (value.insertId !== undefined) text += ` Insert id: ${value.insertId}.`;\n        return [{ type: \"text\", text }];\n      }\n    },\n    async execute(args, exec) {\n      const result = await service.dbExecute({ dbConnectionId: args.db_connection_id, sql: args.sql, params: args.params, signal: exec?.signal, origin: \"agent\" });\n      if (!result.ok) {\n        if (result.error.code === \"unsafe-sql\") {\n          const hasBackup = Array.isArray(result.error.backup) && result.error.backup.length > 0;\n          return {\n            affectedRows: 0, truncated: false, blocked: true,\n            reason: result.error.message, sql: args.sql,\n            ...(hasBackup ? { backup: result.error.backup } : {})\n          };\n        }\n        throw new Error(`db_execute failed: ${result.error.message}`);\n      }\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"db_list_tables\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"List tables in the current schema of a connected MySQL or PostgreSQL database. For MongoDB, use db_run with operation 'countDocuments' on a collection instead.\",\n    parameters: {\n      db_connection_id: { type: \"string\", required: true }\n    },\n    output: {\n      schema: { type: \"object\", additionalProperties: false, properties: { tables: { type: \"array\", required: true, items: { type: \"string\" } } } },\n      render(_args, value) {\n        return [{ type: \"text\", text: value.tables.length ? value.tables.join(\"\\n\") : \"(no tables)\" }];\n      }\n    },\n    async execute(args, exec) {\n      const result = await service.dbListTables({ dbConnectionId: args.db_connection_id, signal: exec?.signal });\n      if (!result.ok) throw new Error(`db_list_tables failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"db_describe_table\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"Full structural introspection of a table in a connected MySQL or PostgreSQL database: columns (name, type, nullable, default), indexes, foreign keys, row-count/data-size estimates from planner statistics, and the MySQL SHOW CREATE TABLE DDL.\",\n    parameters: {\n      db_connection_id: { type: \"string\", required: true },\n      table: { type: \"string\", required: true, description: \"Table name.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\", additionalProperties: false,\n        properties: {\n          table: { type: \"string\", required: true },\n          columns: { type: \"array\", required: true, items: {\n            type: \"object\", additionalProperties: false,\n            properties: {\n              name: { type: \"string\", required: true },\n              type: { type: \"string\", required: true },\n              nullable: { type: \"boolean\", required: true },\n              key: { type: \"string\" },\n              default: { oneOf: [{ type: \"string\" }, { type: \"null\" }, { type: \"number\" }] },\n              extra: { oneOf: [{ type: \"string\" }, { type: \"null\" }] }\n            }\n          }},\n          indexes: { type: \"array\", required: true, items: {\n            type: \"object\", additionalProperties: false,\n            properties: {\n              name: { type: \"string\", required: true },\n              unique: { type: \"boolean\", required: true },\n              columns: { type: \"array\", required: true, items: { type: \"string\" } },\n              definition: { oneOf: [{ type: \"string\" }, { type: \"null\" }], required: true }\n            }\n          }},\n          foreignKeys: { type: \"array\", required: true, items: {\n            type: \"object\", additionalProperties: false,\n            properties: {\n              name: { type: \"string\", required: true },\n              column: { type: \"string\", required: true },\n              foreignTable: { type: \"string\", required: true },\n              foreignColumn: { type: \"string\", required: true }\n            }\n          }},\n          ddl: { oneOf: [{ type: \"string\" }, { type: \"null\" }], required: true },\n          stats: {\n            oneOf: [\n              { type: \"object\", additionalProperties: false, properties: {\n                estimatedRows: { oneOf: [{ type: \"integer\" }, { type: \"null\" }], required: true },\n                dataBytes: { oneOf: [{ type: \"integer\" }, { type: \"null\" }], required: true },\n                indexBytes: { oneOf: [{ type: \"integer\" }, { type: \"null\" }], required: true }\n              } },\n              { type: \"null\" }\n            ],\n            required: true\n          }\n        }\n      },\n      render(args, value) {\n        const lines = [`${args.table}:`];\n        lines.push(value.columns.map((c) => `${c.name}\\t${c.type}\\t${c.nullable ? \"NULL\" : \"NOT NULL\"}${c.default !== undefined && c.default !== null ? `\\tDEFAULT ${c.default}` : \"\"}`).join(\"\\n\"));\n        if (value.indexes?.length) {\n          lines.push(\"\", \"indexes:\");\n          for (const idx of value.indexes) {\n            const cols = idx.columns?.length ? ` (${idx.columns.join(\", \")})` : \"\";\n            const def = idx.definition ? ` — ${idx.definition}` : \"\";\n            lines.push(`  ${idx.name}${idx.unique ? \" UNIQUE\" : \"\"}${cols}${def}`);\n          }\n        }\n        if (value.foreignKeys?.length) {\n          lines.push(\"\", \"foreign keys:\");\n          for (const fk of value.foreignKeys) lines.push(`  ${fk.column} → ${fk.foreignTable}.${fk.foreignColumn} (${fk.name})`);\n        }\n        if (value.stats) {\n          const bits = [];\n          if (value.stats.estimatedRows != null) bits.push(`~${value.stats.estimatedRows} rows`);\n          if (value.stats.dataBytes != null) bits.push(`data ${(value.stats.dataBytes / 1048576).toFixed(2)}MB`);\n          if (value.stats.indexBytes != null) bits.push(`index ${(value.stats.indexBytes / 1048576).toFixed(2)}MB`);\n          if (bits.length) lines.push(\"\", `stats: ${bits.join(\", \")}`);\n        }\n        if (value.ddl) lines.push(\"\", \"DDL:\", value.ddl);\n        return [{ type: \"text\", text: lines.join(\"\\n\") }];\n      }\n    },\n    async execute(args, exec) {\n      const result = await service.dbDescribeTable({ dbConnectionId: args.db_connection_id, table: args.table, signal: exec?.signal });\n      if (!result.ok) throw new Error(`db_describe_table failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"db_preview\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"Sample rows of a table (SELECT * with LIMIT/OFFSET) on a connected MySQL or PostgreSQL database without hand-writing SQL. Returns columns, rows, and a row-count estimate from planner statistics (no full-table COUNT). The table identifier is validated against injection; limit/offset are bound as parameters.\",\n    parameters: {\n      db_connection_id: { type: \"string\", required: true },\n      table: { type: \"string\", required: true, description: \"Table name, optionally schema-qualified (e.g. public.users).\" },\n      limit: { type: \"integer\", description: \"Rows per page, 1-200, default 50.\" },\n      offset: { type: \"integer\", description: \"Rows to skip, default 0 (use for pagination).\" }\n    },\n    output: {\n      schema: {\n        type: \"object\", additionalProperties: false,\n        properties: {\n          table: { type: \"string\", required: true },\n          columns: { type: \"array\", required: true, items: { type: \"string\" } },\n          rows: { type: \"array\", required: true, items: { type: \"object\", additionalProperties: true } },\n          rowCount: { type: \"integer\", required: true },\n          truncated: { type: \"boolean\", required: true },\n          limit: { type: \"integer\", required: true },\n          offset: { type: \"integer\", required: true },\n          estimatedTotal: { oneOf: [{ type: \"integer\" }, { type: \"null\" }], required: true }\n        }\n      },\n      render(_args, value) {\n        const header = value.columns.join(\"\\t\");\n        const body = value.rows.map((r) => value.columns.map((c) => r[c] ?? \"\").join(\"\\t\")).join(\"\\n\");\n        const range = value.rowCount > 0 ? `${value.offset + 1}-${value.offset + value.rowCount}` : \"0\";\n        const est = value.estimatedTotal != null ? ` (estimate ~${value.estimatedTotal})` : \"\";\n        let text = `${value.table} rows ${range}${est}:\\n${header.length > 0 ? `${header}\\n${body}` : \"(empty)\"}`;\n        if (value.truncated) text += \"\\n[truncated to 200 rows]\";\n        return [{ type: \"text\", text }];\n      }\n    },\n    async execute(args, exec) {\n      const result = await service.dbPreview({ dbConnectionId: args.db_connection_id, table: args.table, limit: args.limit, offset: args.offset, signal: exec?.signal });\n      if (!result.ok) throw new Error(`db_preview failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"db_explain\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"Get the execution plan of a SELECT/WITH query (MySQL EXPLAIN FORMAT=JSON / PostgreSQL EXPLAIN (FORMAT JSON)) on a connected database, e.g. to check index usage before optimizing. The statement must pass the same lexically read-only gate as db_query.\",\n    parameters: {\n      db_connection_id: { type: \"string\", required: true },\n      sql: { type: \"string\", required: true, description: \"SELECT or WITH ... SELECT statement to explain.\" },\n      params: { type: \"array\", description: \"Optional parameter values for placeholders.\" }\n    },\n    output: {\n      schema: { type: \"object\", additionalProperties: false, properties: { plan: { type: \"json\", required: true } } },\n      render(_args, value) {\n        return [{ type: \"text\", text: JSON.stringify(value.plan, null, 2) }];\n      }\n    },\n    async execute(args, exec) {\n      const result = await service.dbExplain({ dbConnectionId: args.db_connection_id, sql: args.sql, params: args.params, signal: exec?.signal });\n      if (!result.ok) throw new Error(`db_explain failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"db_export\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"Export the rows of a read-only query (SELECT/WITH, same lexical gate as db_query) as CSV or JSON. When the database is reached through an SSH connection the file is written onto that server (default /tmp/dsh-export-*.{csv,json}) and can be pulled with the SFTP tools; a directly-connected database returns the content inline (small results only). Use for dumping a table or query result, e.g. to hand a CSV to someone or to archive data.\",\n    parameters: {\n      db_connection_id: { type: \"string\", required: true },\n      sql: { type: \"string\", required: true, description: \"SELECT or WITH ... SELECT statement whose rows are exported.\" },\n      format: { type: \"string\", enum: [\"csv\", \"json\"], description: \"Export format; defaults to csv.\" },\n      delimiter: { type: \"string\", enum: [\"comma\", \"tab\", \"semicolon\", \"pipe\"], description: \"CSV field delimiter; defaults to comma.\" },\n      header: { type: \"boolean\", description: \"Include a header row in CSV output; defaults to true.\" },\n      path: { type: \"string\", description: \"Remote path to write to when the connection runs through SSH; defaults to /tmp/dsh-export-<connection>-<timestamp>.<ext>.\" },\n      max_rows: { type: \"integer\", description: \"Row cap for the export; defaults to 50000, maximum 200000.\" },\n      params: { type: \"array\", description: \"Optional parameter values for placeholders.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\", additionalProperties: false,\n        properties: {\n          format: { type: \"string\", required: true },\n          columns: { type: \"array\", required: true, items: { type: \"string\" } },\n          rows: { type: \"integer\", required: true },\n          bytes: { type: \"integer\", required: true },\n          truncated: { type: \"boolean\", required: true },\n          path: { oneOf: [{ type: \"string\" }, { type: \"null\" }], required: true },\n          content: { type: \"string\" }\n        }\n      },\n      render(_args, value) {\n        const where = value.path !== null\n          ? `written to ${value.path} (pull it with the SFTP tools)`\n          : \"returned inline\";\n        const more = value.truncated ? \" [truncated at the row cap]\" : \"\";\n        return [{ type: \"text\", text: `db_export ${value.format}: ${value.rows} row(s), ${value.bytes} bytes ${where}${more}` }];\n      }\n    },\n    async execute(args, exec) {\n      const result = await service.dbExport({\n        dbConnectionId: args.db_connection_id, sql: args.sql, format: args.format,\n        delimiter: args.delimiter, header: args.header, path: args.path,\n        maxRows: args.max_rows, params: args.params, signal: exec?.signal\n      });\n      if (!result.ok) throw new Error(`db_export failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"db_tx_begin\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"Begin an interactive transaction on a dedicated connection (MySQL/PostgreSQL) for verified change workflows: db_tx_begin → db_tx_execute (the write) → db_tx_execute (SELECT to verify) → db_tx_commit or db_tx_rollback. Idle transactions are rolled back automatically after 5 minutes.\",\n    parameters: {\n      db_connection_id: { type: \"string\", required: true }\n    },\n    output: {\n      schema: { type: \"object\", additionalProperties: false, properties: { txId: { type: \"string\", required: true }, dbConnectionId: { type: \"string\", required: true } } },\n      render(_args, value) {\n        return [{ type: \"text\", text: `Transaction ${value.txId} started on ${value.dbConnectionId}. Run db_tx_execute next; finish with db_tx_commit or db_tx_rollback.` }];\n      }\n    },\n    async execute(args, exec) {\n      const result = await service.dbTxBegin({ dbConnectionId: args.db_connection_id, signal: exec?.signal });\n      if (!result.ok) throw new Error(`db_tx_begin failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"db_tx_execute\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"Run one statement inside a transaction opened with db_tx_begin. Use SELECT there to verify the effect of your write before committing. Destructive verbs (DROP/TRUNCATE/SHUTDOWN) remain blocked.\",\n    parameters: {\n      tx_id: { type: \"string\", required: true },\n      sql: { type: \"string\", required: true },\n      params: { type: \"array\", description: \"Optional parameter values for placeholders.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\", additionalProperties: false,\n        properties: {\n          affectedRows: { type: \"integer\", required: true },\n          rowCount: { type: \"integer\", required: true },\n          truncated: { type: \"boolean\", required: true },\n          rows: { type: \"array\", required: true, items: { type: \"object\", additionalProperties: true } },\n          insertId: { oneOf: [{ type: \"integer\" }, { type: \"string\" }] }\n        }\n      },\n      render(_args, value) {\n        if (value.rowCount > 0) {\n          const columns = value.rows[0] ? Object.keys(value.rows[0]) : [];\n          const body = value.rows.map((r) => columns.map((c) => r[c] ?? \"\").join(\"\\t\")).join(\"\\n\");\n          const header = columns.length > 0 ? `${columns.join(\"\\t\")}\\n${body}` : \"(empty)\";\n          const suffix = value.truncated ? \"\\n[truncated to 200 rows]\" : \"\";\n          return [{ type: \"text\", text: `${header}${suffix}` }];\n        }\n        let text = `Affected ${value.affectedRows} row(s).`;\n        if (value.insertId !== undefined) text += ` Insert id: ${value.insertId}.`;\n        return [{ type: \"text\", text }];\n      }\n    },\n    async execute(args, exec) {\n      const result = await service.dbTxExecute({ txId: args.tx_id, sql: args.sql, params: args.params, signal: exec?.signal });\n      if (!result.ok) throw new Error(`db_tx_execute failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"db_tx_commit\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"Commit a transaction opened with db_tx_begin. Call this only after db_tx_execute verification looked right.\",\n    parameters: { tx_id: { type: \"string\", required: true } },\n    output: {\n      schema: { type: \"object\", additionalProperties: false, properties: { txId: { type: \"string\", required: true }, finished: { type: \"boolean\", required: true }, committed: { type: \"boolean\", required: true } } },\n      render(_args, value) { return [{ type: \"text\", text: `Transaction ${value.txId} committed.` }]; }\n    },\n    async execute(args, exec) {\n      const result = await service.dbTxCommit({ txId: args.tx_id, signal: exec?.signal });\n      if (!result.ok) throw new Error(`db_tx_commit failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"db_tx_rollback\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"Roll back a transaction opened with db_tx_begin, undoing every statement executed in it.\",\n    parameters: { tx_id: { type: \"string\", required: true } },\n    output: {\n      schema: { type: \"object\", additionalProperties: false, properties: { txId: { type: \"string\", required: true }, finished: { type: \"boolean\", required: true }, rolledBack: { type: \"boolean\", required: true } } },\n      render(_args, value) { return [{ type: \"text\", text: `Transaction ${value.txId} rolled back.` }]; }\n    },\n    async execute(args, exec) {\n      const result = await service.dbTxRollback({ txId: args.tx_id, signal: exec?.signal });\n      if (!result.ok) throw new Error(`db_tx_rollback failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"db_run\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"Run a command on a connected Redis or MongoDB database. Redis: pass {command, args} (e.g. command='GET', args=['mykey'], or command='KEYS', args=['*']). MongoDB: pass {collection, operation} where operation is 'find'|'findOne'|'insertOne'|'updateOne'|'deleteOne'|'countDocuments', plus filter/document/update as needed. For MySQL/PostgreSQL, use db_query or db_execute instead.\",\n    parameters: {\n      db_connection_id: { type: \"string\", required: true },\n      command: { type: \"string\", description: \"Redis command name (e.g. GET, SET, KEYS, HGETALL).\" },\n      args: { type: \"array\", description: \"Redis command arguments (as strings).\" },\n      collection: { type: \"string\", description: \"MongoDB collection name.\" },\n      operation: { type: \"string\", enum: [\"find\", \"findOne\", \"insertOne\", \"updateOne\", \"deleteOne\", \"countDocuments\"], description: \"MongoDB operation.\" },\n      filter: { type: \"object\", additionalProperties: true, description: \"MongoDB query filter (for find/findOne/updateOne/deleteOne/countDocuments).\" },\n      document: { type: \"object\", additionalProperties: true, description: \"MongoDB document to insert (insertOne).\" },\n      update: { type: \"object\", additionalProperties: true, description: \"MongoDB update spec (updateOne).\" },\n      options: { type: \"object\", additionalProperties: true, description: \"MongoDB update options (updateOne).\" }\n    },\n    output: {\n      schema: { type: \"object\", additionalProperties: false, properties: { result: { type: \"json\" } } },\n      render(_args, value) {\n        const text = typeof value.result === \"string\" ? value.result : JSON.stringify(value.result, null, 2);\n        return [{ type: \"text\", text }];\n      }\n    },\n    async execute(args, exec) {\n      const result = await service.dbRun({\n        dbConnectionId: args.db_connection_id, command: args.command, args: args.args,\n        collection: args.collection, operation: args.operation, filter: args.filter,\n        document: args.document, update: args.update, options: args.options,\n        signal: exec?.signal\n      });\n      if (!result.ok) throw new Error(`db_run failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"db_disconnect\",\n    timeoutMs: DB_TOOL_TIMEOUT_MS,\n    description: \"Close a database connection opened with db_connect. Use it when the user is done querying a database.\",\n    parameters: {\n      db_connection_id: { type: \"string\", required: true }\n    },\n    output: {\n      schema: { type: \"object\", additionalProperties: false, properties: { dbConnectionId: { type: \"string\", required: true }, disconnected: { type: \"boolean\", required: true } } },\n      render(args) { return [{ type: \"text\", text: `Disconnected ${args.db_connection_id}` }]; }\n    },\n    async execute(args, exec) {\n      const result = await service.dbDisconnect({ dbConnectionId: args.db_connection_id, signal: exec?.signal });\n      if (!result.ok) throw new Error(`db_disconnect failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n}\n"
    },
    {
      "path": "src/tools/sftp.js",
      "content": "/**\n * Agent tools for SFTP file management. sftp_delete never deletes on its own:\n * the tools/pre-execute gate suspends the call on the host's approval channel\n * and only an operator \"allow\" lets the body run — as a reversible move to the\n * server trash (see src/trash.js) whenever the path is a simple literal.\n */\nimport { defineTool } from \"@deepseek-ai/dsh-tools\";\nimport { shellQuote } from \"../safety.js\";\nimport { buildTrashCommand, parseSimpleDeleteCommand } from \"../trash.js\";\nimport { t } from \"../i18n/core.js\";\nimport { askOperatorApproval } from \"./ssh-session.js\";\n\nexport function registerSftpTools(ctx, service) {\n  /**\n   * Resolve one SFTP request for the calling session (issue #38). When the\n   * session's workspace is bound to a remote root, a relative path resolves\n   * under that root and an omitted connection_id means the bound server;\n   * otherwise the historical absolute-path/current-connection behavior is\n   * untouched. A path that escapes the bound root is refused here, before any\n   * I/O reaches the server.\n   */\n  const resolveTarget = (exec, connectionId, path) => service.resolveRemoteToolPath({ connectionId, path }, exec);\n  /** Second path of a rename must land on the same server as the first. */\n  const target = (resolved, connectionId) => (connectionId ?? resolved.connectionId);\n\n  // sftp_delete is a deletion by definition, so its gate asks unconditionally:\n  // the whole call suspends until the operator answers, and only \"allow\"\n  // records the voucher the body consumes to actually delete. Deny paths and\n  // hosts without an approval channel degrade to a structured blocked result,\n  // never to a deletion.\n  if (typeof ctx.on === \"function\") ctx.on(\"tools/pre-execute\", (execution, next) => {\n    if (execution?.name !== \"sftp_delete\") return typeof next === \"function\" ? next() : undefined;\n    return (async () => {\n      let preview;\n      try {\n        preview = await resolveTarget(execution, execution.arguments?.connection_id, execution.arguments?.path);\n      } catch {\n        return typeof next === \"function\" ? next() : undefined; // bad path: let the tool report the honest error\n      }\n      const conn = service.connections?.get(preview.connectionId);\n      const host = conn?.host ?? preview.connectionId;\n      const command = `rm -rf ${shellQuote(preview.path)}`;\n      const reason = t(`AI 请求删除 ${host} 上的：\\n${preview.path}\\n（等价于 \\`${command}\\`）。批准后优先执行移入回收站的可逆删除；拒绝则不会删除任何内容。`);\n      const { outcome } = await askOperatorApproval(ctx, execution, reason);\n      if (outcome === \"allowed-once\") {\n        service.recordOperatorApproval(execution.callId, preview.connectionId, command);\n        return typeof next === \"function\" ? next() : undefined;\n      }\n      const denied = outcome === \"rejected\"\n        ? t(`操作者拒绝了删除 ${preview.path}。请勿重试或换路径绕行；确需删除请让操作者自行处理。`)\n        : outcome === \"cancelled\"\n          ? t(\"删除操作的确认被取消，未删除任何内容。请勿重试；确需删除请与操作者确认。\")\n          : t(`删除 ${preview.path} 必须由操作者确认，但当前宿主没有可用的审批通道，未删除任何内容。请让操作者自行删除。`);\n      return { kind: \"deny\", reason: denied };\n    })();\n  });\n\n  ctx.tools.register(defineTool({\n    name: \"sftp_list\",\n    description: \"List the entries of a remote directory over SFTP on a connected server (the one open in the right-side SSH terminal unless connection_id is given). In a remote workspace a relative path resolves under the bound remote root. Returns file/directory entries with sizes and mtimes.\",\n    parameters: {\n      connection_id: { type: \"string\", description: \"Connection id from ssh_connect; omit to use the current server (or the remote workspace's bound server).\" },\n      path: { type: \"string\", required: true, description: \"Remote directory path, e.g. /etc or /var/log. Relative values resolve under the remote workspace root.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\",\n        additionalProperties: false,\n        properties: {\n          path: { type: \"string\", required: true },\n          entries: { type: \"array\", required: true, items: { type: \"object\", additionalProperties: false, properties: {\n            name: { type: \"string\", required: true },\n            isDirectory: { type: \"boolean\", required: true },\n            size: { type: \"number\", required: true },\n            mtime: { type: \"number\", required: true },\n            mode: { type: \"number\", required: true }\n          } } }\n        }\n      },\n      render(args, value) {\n        if (!value.entries.length) return [{ type: \"text\", text: `(empty directory ${value.path})` }];\n        const lines = value.entries.map((e) => `${e.isDirectory ? \"d\" : \"-\"} ${e.isDirectory ? \"\" : String(e.size).padStart(10)}  ${new Date(e.mtime).toISOString().slice(0, 16).replace(\"T\", \" \")}  ${e.name}`);\n        return [{ type: \"text\", text: `Directory ${value.path} (${value.entries.length} entries):\\n` + lines.join(\"\\n\") }];\n      }\n    },\n    async execute(args, exec) {\n      const target = await resolveTarget(exec, args.connection_id, args.path);\n      const result = await service.sftpList({ connectionId: target.connectionId, path: target.path });\n      if (!result.ok) throw new Error(`sftp_list failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"sftp_read\",\n    description: \"Read a remote file over SFTP. The data field is base64-encoded file content; decode it to text when inspecting text files. Useful for config files, logs, or small artifacts on a connected server. Omit connection_id for the current server.\",\n    parameters: {\n      connection_id: { type: \"string\", description: \"Connection id from ssh_connect; omit to use the current server.\" },\n      path: { type: \"string\", required: true, description: \"Remote file path. A relative path resolves under the remote workspace root.\" },\n      max_bytes: { type: \"integer\", description: \"Maximum bytes to read, defaults to 4 MiB.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\",\n        additionalProperties: false,\n        properties: {\n          path: { type: \"string\", required: true },\n          data: { type: \"string\", required: true },\n          truncated: { type: \"boolean\", required: true },\n          bytes: { type: \"number\", required: true }\n        }\n      },\n      render(args, value) {\n        const body = value.data || \"(empty file)\";\n        const returnedBytes = Buffer.from(value.data || \"\", \"base64\").length;\n        return [{ type: \"text\", text: value.truncated ? `${body}\\n[output truncated after ${returnedBytes} of ${value.bytes} bytes]` : body }];\n      }\n    },\n    async execute(args, exec) {\n      const target = await resolveTarget(exec, args.connection_id, args.path);\n      const result = await service.sftpReadFile({ connectionId: target.connectionId, path: target.path, maxBytes: args.max_bytes });\n      if (!result.ok) throw new Error(`sftp_read failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"sftp_write\",\n    description: \"Write text content to a remote file over SFTP (creates or overwrites). Omit connection_id for the current server.\",\n    parameters: {\n      connection_id: { type: \"string\", description: \"Connection id from ssh_connect; omit to use the current server.\" },\n      path: { type: \"string\", required: true, description: \"Remote file path to write. A relative path resolves under the remote workspace root.\" },\n      content: { type: \"string\", required: true, description: \"File content to write.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\",\n        additionalProperties: false,\n        properties: {\n          path: { type: \"string\", required: true },\n          bytes: { type: \"number\", required: true }\n        }\n      },\n      render(args, value) {\n        return [{ type: \"text\", text: `Wrote ${value.bytes} bytes to ${value.path}` }];\n      }\n    },\n    async execute(args, exec) {\n      const target = await resolveTarget(exec, args.connection_id, args.path);\n      const result = await service.sftpWriteFile({ connectionId: target.connectionId, path: target.path, data: Buffer.from(args.content, \"utf8\").toString(\"base64\") });\n      if (!result.ok) throw new Error(`sftp_write failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"sftp_mkdir\",\n    description: \"Create a remote directory over SFTP. Omit connection_id for the current server.\",\n    parameters: {\n      connection_id: { type: \"string\", description: \"Connection id from ssh_connect; omit to use the current server.\" },\n      path: { type: \"string\", required: true, description: \"Remote directory path to create. A relative path resolves under the remote workspace root.\" }\n    },\n    output: {\n      schema: { type: \"object\", additionalProperties: false, properties: { path: { type: \"string\", required: true } } },\n      render(args, value) { return [{ type: \"text\", text: `Created directory ${value.path}` }]; }\n    },\n    async execute(args, exec) {\n      const target = await resolveTarget(exec, args.connection_id, args.path);\n      const result = await service.sftpMkdir({ connectionId: target.connectionId, path: target.path });\n      if (!result.ok) throw new Error(`sftp_mkdir failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"sftp_delete\",\n    description: \"Delete a remote file or directory over SFTP. Omit connection_id for the current server. Deletion suspends this call until the operator answers the host's confirmation prompt in the conversation: approving performs a reversible move to the server trash when the path is a simple literal (a real deletion otherwise), rejecting deletes nothing — never retry or route around a rejection.\",\n    parameters: {\n      connection_id: { type: \"string\", description: \"Connection id from ssh_connect; omit to use the current server.\" },\n      path: { type: \"string\", required: true, description: \"Remote path to delete. A relative path resolves under the remote workspace root.\" }\n    },\n    output: {\n      schema: { type: \"object\", additionalProperties: false, properties: { path: { type: \"string\", required: true }, isDirectory: { type: \"boolean\" }, blocked: { type: \"boolean\" }, reason: { type: \"string\" }, command: { type: \"string\" } } },\n      render(args, value) {\n        if (value.blocked) {\n          return [{ type: \"text\", text: t(`⚠️ 已拦截：${value.reason ?? \"\"}\\n未删除任何内容。删除必须由操作者确认，本次调用没有获得批准（操作者拒绝，或宿主没有可用的审批通道）。\\n\\`\\`\\`bash\\n${value.command ?? \"\"}\\n\\`\\`\\`\\n请勿重试或换路径绕行；把删除交给操作者自行处理。`) }];\n        }\n        return [{ type: \"text\", text: `Deleted ${value.path}` }];\n      }\n    },\n    async execute(args, exec) {\n      // The pre-execute gate asked the operator and, on \"allow\", recorded a\n      // voucher under this execution's id; it is consumed here exactly once.\n      // In a remote workspace the ask always names the resolved absolute\n      // path, so the operator sees exactly what would be removed.\n      const resolved = await resolveTarget(exec, args.connection_id, args.path);\n      const command = `rm -rf ${shellQuote(resolved.path)}`;\n      const parsed = parseSimpleDeleteCommand(command);\n      const trashScript = parsed ? buildTrashCommand(parsed.targets) : null;\n      if (!(exec?.callId !== undefined && service.consumeOperatorApproval(exec.callId, resolved.connectionId, command))) {\n        return { path: resolved.path, blocked: true, reason: t(\"删除文件或目录（SFTP）\"), command };\n      }\n      // Approved: the reversible trash move is what actually runs whenever\n      // the path allows it; only a non-parseable path deletes for real.\n      const result = await service.runPreparedExec(resolved.connectionId, trashScript ?? command, command, true, 30000, false, false);\n      if (!result.ok) throw new Error(`sftp_delete failed: ${result.error.message}`);\n      if (result.value.timedOut || result.value.exitCode !== 0) {\n        const detail = result.value.stderr?.trim() || `exit code ${result.value.exitCode ?? \"unknown\"}`;\n        throw new Error(`sftp_delete outcome is not successful: ${detail}`);\n      }\n      return { path: resolved.path };\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"sftp_rename\",\n    description: \"Rename or move a remote file/directory over SFTP. Omit connection_id for the current server.\",\n    parameters: {\n      connection_id: { type: \"string\", description: \"Connection id from ssh_connect; omit to use the current server.\" },\n      from: { type: \"string\", required: true, description: \"Current remote path. A relative path resolves under the remote workspace root.\" },\n      to: { type: \"string\", required: true, description: \"New remote path. A relative path resolves under the remote workspace root.\" }\n    },\n    output: {\n      schema: { type: \"object\", additionalProperties: false, properties: { from: { type: \"string\", required: true }, to: { type: \"string\", required: true } } },\n      render(args, value) { return [{ type: \"text\", text: `Renamed ${value.from} -> ${value.to}` }]; }\n    },\n    async execute(args, exec) {\n      const file = await resolveTarget(exec, args.connection_id, args.from);\n      const destination = await resolveTarget(exec, target(file, args.connection_id), args.to);\n      const result = await service.sftpRename({ connectionId: file.connectionId, from: file.path, to: destination.path });\n      if (!result.ok) throw new Error(`sftp_rename failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"sftp_upload_dir\",\n    description: \"Upload a local directory tree to a remote server over SFTP, creating the remote directory structure. Small files transfer in parallel (bounded), large files one at a time for full link throughput. Per-file failures are reported, not fatal. Omit connection_id for the current server.\",\n    parameters: {\n      connection_id: { type: \"string\", description: \"Connection id from ssh_connect; omit to use the current server.\" },\n      local_path: { type: \"string\", required: true, description: \"Local directory to upload.\" },\n      remote_path: { type: \"string\", required: true, description: \"Remote destination directory (created when missing).\" }\n    },\n    output: {\n      schema: {\n        type: \"object\",\n        additionalProperties: false,\n        properties: {\n          source: { type: \"string\", required: true },\n          target: { type: \"string\", required: true },\n          directories: { type: \"number\", required: true },\n          files: { type: \"number\", required: true },\n          bytes: { type: \"number\", required: true },\n          failed: { type: \"array\", required: true, items: { type: \"object\", additionalProperties: false, properties: { path: { type: \"string\", required: true }, error: { type: \"string\", required: true } } } }\n        }\n      },\n      render(args, value) {\n        const head = `Uploaded ${value.files} files (${value.bytes} bytes, ${value.directories} directories) to ${value.target}`;\n        if (!value.failed.length) return [{ type: \"text\", text: head }];\n        const lines = value.failed.map((f) => `- ${f.path}: ${f.error}`);\n        return [{ type: \"text\", text: `${head}\\n${value.failed.length} failures:\\n${lines.join(\"\\n\")}` }];\n      }\n    },\n    async execute(args, exec) {\n      const target = await resolveTarget(exec, args.connection_id, args.remote_path);\n      const result = await service.sftpUploadDir({\n        connectionId: target.connectionId,\n        localPath: args.local_path,\n        remotePath: target.path,\n        signal: exec?.signal,\n        ...(target.bound ? { remoteWorkspaceRoot: target.workspaceRoot } : {})\n      });\n      if (!result.ok) throw new Error(`sftp_upload_dir failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"sftp_download_dir\",\n    description: \"Download a remote directory tree over SFTP to a local directory, recreating the structure. Small files transfer in parallel (bounded), large files one at a time. Per-file failures are reported, not fatal. Omit connection_id for the current server.\",\n    parameters: {\n      connection_id: { type: \"string\", description: \"Connection id from ssh_connect; omit to use the current server.\" },\n      remote_path: { type: \"string\", required: true, description: \"Remote directory to download.\" },\n      local_path: { type: \"string\", required: true, description: \"Local destination directory (created when missing).\" }\n    },\n    output: {\n      schema: {\n        type: \"object\",\n        additionalProperties: false,\n        properties: {\n          source: { type: \"string\", required: true },\n          target: { type: \"string\", required: true },\n          directories: { type: \"number\", required: true },\n          files: { type: \"number\", required: true },\n          bytes: { type: \"number\", required: true },\n          failed: { type: \"array\", required: true, items: { type: \"object\", additionalProperties: false, properties: { path: { type: \"string\", required: true }, error: { type: \"string\", required: true } } } }\n        }\n      },\n      render(args, value) {\n        const head = `Downloaded ${value.files} files (${value.bytes} bytes, ${value.directories} directories) to ${value.target}`;\n        if (!value.failed.length) return [{ type: \"text\", text: head }];\n        const lines = value.failed.map((f) => `- ${f.path}: ${f.error}`);\n        return [{ type: \"text\", text: `${head}\\n${value.failed.length} failures:\\n${lines.join(\"\\n\")}` }];\n      }\n    },\n    async execute(args, exec) {\n      const target = await resolveTarget(exec, args.connection_id, args.remote_path);\n      const result = await service.sftpDownloadDir({\n        connectionId: target.connectionId,\n        remotePath: target.path,\n        localPath: args.local_path,\n        signal: exec?.signal\n      });\n      if (!result.ok) throw new Error(`sftp_download_dir failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n}\n"
    },
    {
      "path": "src/tools/ssh-session.js",
      "content": "/**\n * Agent tools for the SSH session lifecycle: list, connect, exec, read,\n * write, disconnect. All of them drive the same connections/sessions the\n * right-side panel shows; `service` is the SshOpsService instance.\n */\nimport { defineTool } from \"@deepseek-ai/dsh-tools\";\nimport { assessShellCommand, CATEGORY_DELETE_FILES } from \"../safety.js\";\nimport { parseSimpleDeleteCommand } from \"../trash.js\";\nimport { t } from \"../i18n/core.js\";\n\n/** Human name for an execution-policy tier, for agent-facing notices. */\nexport function execPolicyLabel(mode) {\n  if (mode === \"custom\") return t(\"自定义放行\");\n  if (mode === \"allowAll\") return t(\"全部放行\");\n  return t(\"标准\");\n}\n\n/**\n * Ask the operator through the host's approval channel. Returns the raw\n * outcome (\"allowed-once\" | \"rejected\" | \"cancelled\" | \"unavailable\") so the\n * gate can grant precisely, and degrades to \"unavailable\" whenever the host\n * composes no approval service, exposes none to plugins, or the call has no\n * agent to route the prompt to — fail-closed in every direction.\n */\nexport async function askOperatorApproval(ctx, execution, reason) {\n  let approval;\n  try { approval = ctx.get(\"approval\"); } catch { approval = undefined; }\n  if (approval === undefined || execution?.agent === undefined || execution?.callId === undefined) {\n    return { outcome: \"unavailable\" };\n  }\n  try {\n    const outcome = await approval.request({\n      agent: execution.agent,\n      toolName: execution.name,\n      callId: execution.callId,\n      reason,\n      signal: execution.signal\n    });\n    return { outcome: typeof outcome === \"string\" ? outcome : \"unavailable\" };\n  } catch {\n    return { outcome: \"unavailable\" };\n  }\n}\n\nexport function registerSshSessionTools(ctx, service) {\n  // Dangerous-command gate for ssh_exec: the tools/pre-execute waterfall\n  // evaluates the exact policy the exec path will enforce and, when the\n  // command is deny-listed, suspends the whole call on the host's approval\n  // channel — the agent cannot act, retry, or route around while the\n  // operator decides. On \"allow\" a one-shot voucher (callId -> connection +\n  // command) is recorded for the tool body to consume past the inner gate.\n  // No approval channel at all degrades to deny, never to execute.\n  if (typeof ctx.on === \"function\") ctx.on(\"tools/pre-execute\", (execution, next) => {\n    if (execution?.name !== \"ssh_exec\") return typeof next === \"function\" ? next() : undefined;\n    return (async () => {\n      const command = typeof execution.arguments?.command === \"string\" ? execution.arguments.command : \"\";\n      const selected = service.resolveConnection(execution.arguments?.connection_id);\n      if (!selected.ok) return typeof next === \"function\" ? next() : undefined; // no target: let the tool report the honest error\n      const policy = service.resolveExecPolicy(selected.connectionId);\n      const decision = assessShellCommand(command, policy);\n      if (decision.ok) return typeof next === \"function\" ? next() : undefined;\n      let trashNote = \"\";\n      if (decision.category === CATEGORY_DELETE_FILES && parseSimpleDeleteCommand(command)) {\n        trashNote = t(\"（批准后实际执行的是移入回收站的可逆操作，不会真删）\");\n      }\n      const host = selected.connection.host ?? \"\";\n      const reason = t(`AI 请求在 ${host} 上执行危险命令，已被执行策略（${execPolicyLabel(policy.mode)}）拦截：\\n${command}\\n风险类别：${t(decision.category ?? decision.reason)}${trashNote}\\n批准=本次执行；拒绝=命令不会运行。`);\n      const { outcome } = await askOperatorApproval(ctx, execution, reason);\n      if (outcome === \"allowed-once\") {\n        service.recordOperatorApproval(execution.callId, selected.connectionId, command);\n        return typeof next === \"function\" ? next() : undefined;\n      }\n      if (outcome === \"rejected\") {\n        return { kind: \"deny\", reason: t(`操作者拒绝了该危险命令（${command}）。请勿重试或换写法绕行；如确需执行，请让操作者自行在终端运行，或请其调整右侧面板的执行策略。`) };\n      }\n      if (outcome === \"cancelled\") {\n        return { kind: \"deny\", reason: t(\"危险命令的确认被取消，命令未执行。请勿重试；如确需执行请与操作者确认。\") };\n      }\n      return { kind: \"deny\", reason: t(`该命令属于危险操作（${t(decision.category ?? decision.reason)}），必须由操作者确认，但当前宿主没有可用的审批通道，命令未执行。请勿重试或绕行；请操作者直接在终端手动执行。`) };\n    })();\n  });\n\n  ctx.tools.register(defineTool({\n    name: \"ssh_shell_integration\",\n    description: \"Enable shell integration (OSC 133 markers) in an open SSH terminal's bash/zsh shell. Afterwards ssh_terminal_context reports the shell's current directory, the last command's exit code and whether it sits at a prompt — far more reliable than guessing from output text. Requires an idle, single interactive shell; the session must be one from ssh_terminal_sessions.\",\n    parameters: { session_id: { type: \"string\", required: true, description: \"Session id from ssh_terminal_sessions.\" } },\n    output: {\n      schema: { type: \"object\", additionalProperties: false, properties: { sessionId: { type: \"string\", required: true }, enabled: { type: \"boolean\", required: true } } },\n      render(_args, value) {\n        return [{ type: \"text\", text: value.enabled ? t(`已在会话 ${value.sessionId} 启用 shell integration；此后 ssh_terminal_context 会带上 cwd/退出码/提示符状态。`) : t(\"启用失败。\") }];\n      }\n    },\n    async execute(args) {\n      const result = await service.enableShellIntegration({ sessionId: args.session_id });\n      if (!result.ok) throw new Error(`ssh_shell_integration failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"ssh_terminal_sessions\",\n    description: \"List open SSH terminal sessions so you can identify a terminal the user operated manually. Returns metadata and history cursors only; never returns terminal output, saved resources, or credentials.\",\n    parameters: {},\n    output: {\n      schema: { type: \"object\", additionalProperties: false, properties: { sessions: { type: \"array\", required: true, items: { type: \"object\", additionalProperties: true } } } },\n      render(_args, value) { return [{ type: \"text\", text: JSON.stringify(value, null, 2) }]; }\n    },\n    async execute() { const result = service.listTerminalContexts(); if (!result.ok) throw new Error(`ssh_terminal_sessions failed: ${result.error.message}`); return result.value; }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"ssh_terminal_context\",\n    description: \"Read a bounded, redacted range from a user-operated SSH terminal after approval. Use ssh_terminal_sessions first to select a session. This does not consume or alter the visible terminal history.\",\n    parameters: { session_id: { type: \"string\", required: true }, after: { type: \"integer\", description: \"Optional cursor from a previous read.\" }, max_bytes: { type: \"integer\", description: \"1024..98304 bytes; defaults to 24576.\" } },\n    output: {\n      schema: { type: \"object\", additionalProperties: true },\n      render(_args, value) { return [{ type: \"text\", text: JSON.stringify(value, null, 2) }]; }\n    },\n    async execute(args) { const result = service.readTerminalContext({ sessionId: args.session_id, after: args.after, maxBytes: args.max_bytes }); if (!result.ok) throw new Error(`ssh_terminal_context failed: ${result.error.message}`); return result.value; }\n  }));\n\n  if (typeof ctx.on === \"function\") ctx.on(\"tools/pre-execute\", (execution, next) => {\n    if (execution?.name !== \"ssh_terminal_context\") return typeof next === \"function\" ? next() : undefined;\n    return { kind: \"ask\", reason: \"Agent requests recent manual SSH terminal activity, which may contain sensitive output.\" };\n  });\n\n  ctx.tools.register(defineTool({\n    name: \"ssh_list\",\n    description: t(\"List currently open SSH connections and identify the active server. This reports only live connection metadata (name, host, port, username and active state); it never returns credentials. When the operator enabled 「允许 AI 自动连接已保存服务器」 in the SSH settings, the result also lists the operator's saved SSH resources (name, host, username, whether already connected) — connect one with ssh_connect_profile. Use this tool when the user asks which server is connected or which saved servers exist; for normal server work, ssh_exec/ssh_read/ssh_write already target the active connection automatically.\"),\n    parameters: {},\n    output: {\n      schema: {\n        type: \"object\",\n        additionalProperties: false,\n        properties: {\n          activeConnectionId: { oneOf: [{ type: \"string\" }, { type: \"null\" }], required: true },\n          connections: {\n            type: \"array\",\n            required: true,\n            items: {\n              type: \"object\",\n              additionalProperties: false,\n              properties: {\n                connectionId: { type: \"string\", required: true },\n                name: { type: \"string\" },\n                host: { type: \"string\", required: true },\n                port: { type: \"integer\", required: true },\n                username: { type: \"string\", required: true },\n                connected: { type: \"boolean\", required: true },\n                sessions: { type: \"array\", required: true, items: { type: \"string\" } },\n                agentSession: { type: \"boolean\" },\n                agentRevealId: { type: \"string\" }\n              }\n            }\n          },\n          resources: {\n            type: \"array\",\n            items: {\n              type: \"object\",\n              additionalProperties: false,\n              properties: {\n                profileId: { type: \"string\", required: true },\n                name: { type: \"string\", required: true },\n                host: { type: \"string\", required: true },\n                port: { type: \"integer\", required: true },\n                username: { type: \"string\", required: true },\n                connected: { type: \"boolean\", required: true }\n              }\n            }\n          }\n        }\n      },\n      render(_args, value) {\n        const lines = [];\n        if (value.connections.length === 0) lines.push(\"No SSH connection is currently open.\");\n        else lines.push(...value.connections.map((connection) => `${connection.connectionId === value.activeConnectionId ? \"* \" : \"- \"}${connection.name ?? connection.host}: ${connection.username}@${connection.host}:${connection.port}${connection.sessions.length ? \" (terminal open)\" : \"\"}`));\n        if (value.resources !== undefined) {\n          lines.push(\"\");\n          lines.push(value.resources.length === 0\n            ? t(\"Saved SSH resources: none saved yet — the operator can add servers in 设置 → SSH 资源.\")\n            : `Saved SSH resources (connectable via ssh_connect_profile): ${value.resources.map((resource) => `${resource.name} → ${resource.username}@${resource.host}:${resource.port}${resource.connected ? \" [connected]\" : \"\"}`).join(\"; \")}`);\n        }\n        return [{ type: \"text\", text: lines.join(\"\\n\") }];\n      }\n    },\n    async execute() {\n      const result = await service.list();\n      if (!result.ok) throw new Error(`ssh_list failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"ssh_connect\",\n    description: \"Connect to a remote server over SSH, open it in the right-side terminal, and make it the current connection for later SSH tools. Subsequent ssh_exec, ssh_read, ssh_write, and ssh_disconnect calls automatically use this connection unless a connection_id is explicitly supplied.\",\n    parameters: {\n      host: { type: \"string\", required: true, description: \"Remote hostname or IP address.\" },\n      port: { type: \"integer\", description: \"SSH port, defaults to 22.\" },\n      username: { type: \"string\", required: true, description: \"SSH username.\" },\n      auth: {\n        type: \"object\",\n        required: true,\n        additionalProperties: false,\n        description: \"Authentication. Either {kind: 'password', password} or {kind: 'key', privateKey, passphrase?}.\",\n        properties: {\n          kind: { type: \"string\", enum: [\"password\", \"key\"], required: true },\n          password: { type: \"string\" },\n          privateKey: { type: \"string\" },\n          passphrase: { type: \"string\" }\n        }\n      },\n      legacy: { type: \"boolean\", description: \"Only for old network devices (Huawei legacy VRP e.g. S12712, some old IOS/Comware) that offer no modern SSH key exchange. Omit it and the plugin retries automatically once if the handshake fails on key-exchange selection, returning legacyFallback. Pass true to use the legacy algorithm set immediately, or false to forbid the automatic retry.\" },\n      name: { type: \"string\", description: \"Optional display name for this connection.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\",\n        additionalProperties: false,\n        properties: {\n          connectionId: { type: \"string\", required: true },\n          name: { type: \"string\" },\n          host: { type: \"string\", required: true },\n          port: { type: \"integer\", required: true },\n          username: { type: \"string\", required: true },\n          legacyFallback: { type: \"boolean\" },\n          bannerRepair: { type: \"boolean\" },\n          warning: { type: \"string\" }\n        }\n      },\n      render(args, value) {\n        const conn = value ?? {};\n        const base = `Connected ${args.username}@${args.host} (id: ${conn.connectionId ?? \"?\"})`;\n        // Anything unusual about the handshake must be visible in the tool\n        // result, not only in the host log — a weakened transport or a rewritten\n        // banner is something the operator has to know about to act on it.\n        return [{ type: \"text\", text: conn.warning ? `${base}\\n⚠️ ${conn.warning}` : base }];\n      }\n    },\n    async execute(args) {\n      const result = await service.connect({\n        host: args.host,\n        port: args.port,\n        username: args.username,\n        auth: args.auth,\n        legacy: args.legacy,\n        name: args.name\n      });\n      if (!result.ok) throw new Error(`ssh_connect failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"ssh_connect_profile\",\n    description: t(\"Connect to one of the operator's saved SSH resources (设置 → SSH 资源) by name and make it the active connection: later ssh_exec/ssh_read/ssh_write without connection_id target it, and its terminal opens in the right-side panel so the operator can see which machine you are on. Only works when the operator enabled 「允许 AI 自动连接已保存服务器」; with the switch off the call fails — then ask the operator to connect the server, and NEVER fall back to ssh_connect with credentials you gathered from conversation. Reuses an already-open connection for the same resource instead of connecting twice.\"),\n    parameters: {\n      resource: { type: \"string\", required: true, description: \"The saved resource's name as shown by ssh_list (e.g. 'dev', 'prod'), or its profile id. A unique partial name is accepted; unknown or ambiguous names fail with the list of available resources.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\",\n        additionalProperties: false,\n        properties: {\n          connectionId: { type: \"string\", required: true },\n          profileId: { type: \"string\", required: true },\n          name: { type: \"string\", required: true },\n          host: { type: \"string\", required: true },\n          port: { type: \"integer\", required: true },\n          username: { type: \"string\", required: true },\n          reused: { type: \"boolean\", required: true },\n          terminalOpened: { type: \"boolean\", required: true },\n          warning: { type: \"string\" }\n        }\n      },\n      render(_args, value) {\n        const base = t(`已连接保存的服务器「${value.name}」（${value.username}@${value.host}:${value.port}，id: ${value.connectionId}），并已设为当前 SSH 连接，后续 ssh_exec 等工具默认作用于这台机器。${value.reused ? t(\"复用了该服务器已有的连接。\") : \"\"}${value.terminalOpened ? t(\"已为它打开终端会话（可在右侧 SSH 面板查看该机器）。\") : \"\"}`);\n        return [{ type: \"text\", text: value.warning ? `${base}\\n⚠️ ${value.warning}` : base }];\n      }\n    },\n    async execute(args) {\n      const result = await service.agentConnectProfile({ resource: args.resource });\n      if (!result.ok) throw new Error(`ssh_connect_profile failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"ssh_exec\",\n    description: \"Run a normal SSH command on the server currently open in the right-side SSH terminal and return its output. This runs one non-interactive command and returns when it finishes. Tasks that need terminal interaction — switching users (sudo -i / su), entering a container (docker exec -it), or connecting onward to another machine (ssh) — do not fit here; run those with ssh_write in the interactive terminal instead. Omit connection_id when the user means the current server; do not call ssh_list first. On Linux with one identifiable idle POSIX terminal shell, the dedicated exec channel starts in that shell's verified current directory. A busy, ambiguous, or inaccessible terminal directory rejects the command instead of guessing; when no terminal shell is detectable, the normal login directory is used and cwd is null. SSH configuration, package changes, service reloads, and config edits are allowed and remain subject to DSH permissions. Explicitly destructive or irreversible commands suspend this call until the operator answers the host's confirmation prompt in the conversation: approving runs the command once, rejecting denies it — never retry or route around a rejection. The command and output are also shown in the terminal panel.\",\n    parameters: {\n      connection_id: { type: \"string\", description: \"Optional. Omit to target the current right-side SSH connection.\" },\n      command: { type: \"string\", required: true, description: \"The shell command to execute.\" },\n      timeout_ms: { type: \"integer\", description: \"Timeout in milliseconds, defaults to 30000.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\",\n        additionalProperties: false,\n        properties: {\n          connectionId: { type: \"string\", required: true },\n          host: { type: \"string\", required: true },\n          exitCode: { oneOf: [{ type: \"integer\" }, { type: \"null\" }], required: true },\n          stdout: { type: \"string\", required: true },\n          stderr: { type: \"string\", required: true },\n          cwd: { oneOf: [{ type: \"string\" }, { type: \"null\" }], required: true },\n          commandId: { type: \"string\", required: true },\n          startedAt: { type: \"string\", required: true },\n          finishedAt: { type: \"string\", required: true },\n          durationMs: { type: \"integer\", required: true },\n          truncated: { type: \"boolean\", required: true },\n          timedOut: { type: \"boolean\", required: true },\n          redacted: { type: \"boolean\", required: true },\n          blocked: { type: \"boolean\" },\n          reason: { type: \"string\" },\n          command: { type: \"string\" },\n          policy: { type: \"string\" },\n          policySource: { type: \"string\" }\n        }\n      },\n      render(args, value) {\n        if (value.blocked) {\n          const tierNote = value.policy\n            ? \"\\n\" + t(`当前连接执行策略：${execPolicyLabel(value.policy)}${value.policySource === \"session\" ? t(\"（操作者本次会话内切换）\") : \"\"}。若操作者希望放开此类命令，请其自行在右侧面板的策略开关中调整；请勿重试。`)\n            : \"\";\n          return [{ type: \"text\", text: t(`⚠️ 已拦截：${value.reason ?? \"\"}\\n命令未执行。危险命令必须由操作者确认，本次调用没有获得批准（操作者拒绝，或宿主没有可用的审批通道）。\\n\\`\\`\\`bash\\n${value.command ?? \"\"}\\n\\`\\`\\`\\n请勿重试或换写法绕行；把命令交给操作者自行执行，或请其调整执行策略。`) + tierNote }];\n        }\n        const out = value.stdout ?? \"\";\n        const err = value.stderr ?? \"\";\n        let body = out;\n        if (err.length > 0) {\n          if (body.length > 0 && !body.endsWith(\"\\n\")) body += \"\\n\";\n          body += `[stderr]\\n${err}`;\n        }\n        if (body.length === 0) body = \"(no output)\";\n        if (value.exitCode !== null && value.exitCode !== 0) body += `\\n[exit code: ${value.exitCode}]`;\n        if (value.timedOut) body += \"\\n[command timed out]\";\n        if (value.truncated) body += \"\\n[output truncated for safe model context]\";\n        if (value.redacted) body += \"\\n[sensitive values redacted]\";\n        // Where the command ran. First line, so relative-path output always\n        // has its context above it; null spells out the home fallback.\n        const cwdNote = value.cwd\n          ? `[cwd: ${value.cwd}]`\n          : \"[cwd: login directory — no interactive shell directory detected]\";\n        return [{ type: \"text\", text: `${cwdNote}\\n${body}` }];\n      }\n    },\n    async execute(args, exec) {\n      const result = await service.executeCommand({\n        connectionId: args.connection_id,\n        command: args.command,\n        timeoutMs: args.timeout_ms ?? 30000,\n        // The pre-execute gate records its voucher under the execution id;\n        // the inner gate consumes it so an operator-approved command runs.\n        approvalToken: exec?.callId\n      });\n      if (!result.ok) throw new Error(`ssh_exec failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"ssh_read\",\n    description: \"Read output from the current right-side SSH terminal. Omit connection_id for the current server; do not call ssh_list first. By default only output that arrived since your previous ssh_read on this connection is returned — results you already received are not repeated, so read again after ssh_write without re-paying for old output. Pass mode \\\"tail\\\" for the full recent terminal capture instead (e.g. output that predates your first read, or something that scrolled past). Also useful when the user typed something in the panel.\",\n    parameters: {\n      connection_id: { type: \"string\", description: \"Optional. Omit to target the current right-side SSH connection.\" },\n      mode: { type: \"string\", enum: [\"new\", \"tail\"], description: \"'new' (default) returns only output that arrived since the previous ssh_read on this connection; 'tail' returns the whole recent terminal capture. Use 'tail' sparingly — it repeats output you likely already have.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\",\n        additionalProperties: false,\n        properties: {\n          connectionId: { type: \"string\", required: true },\n          host: { type: \"string\", required: true },\n          data: { type: \"string\", required: true },\n          hasSession: { type: \"boolean\", required: true },\n          truncated: { type: \"boolean\", required: true },\n          redacted: { type: \"boolean\", required: true }\n        }\n      },\n      render(args, value) {\n        const body = !value.hasSession\n          ? \"(no open shell session on this connection)\"\n          : value.data || (args.mode === \"tail\" ? \"(no output yet)\" : \"(no new output since the previous read)\");\n        const notes = [\n          value.truncated ? \"[terminal capture truncated]\" : \"\",\n          value.redacted ? \"[sensitive values redacted]\" : \"\"\n        ].filter(Boolean);\n        return [{ type: \"text\", text: notes.length > 0 ? `${body}\\n${notes.join(\"\\n\")}` : body }];\n      }\n    },\n    async execute(args) {\n      const result = service.readCurrentConnection({ connectionId: args.connection_id, mode: args.mode });\n      if (!result.ok) throw new Error(`ssh_read failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"ssh_write\",\n    description: \"Send input into a right-side SSH terminal and, by default, press Enter afterwards so the input is submitted like a human typing Enter (a carriage return \\\\r is appended unless the input already ends with a newline). Omit connection_id to target the current/active terminal; provide connection_id to target a specific server's terminal. If the target connection has no open terminal, one is opened automatically so the input is never silently dropped. Normal operations are permitted through DSH permissions; explicitly destructive or irreversible commands are stopped before agent execution. Ctrl-C remains available to cancel an in-progress command.\",\n    parameters: {\n      connection_id: { type: \"string\", description: \"Optional. Omit to target the current/active terminal; specify to target that server's terminal (e.g. from ssh_connect/ssh_list).\" },\n      input: { type: \"string\", required: true, description: \"The input to send, e.g. 'y' to answer a prompt, or 'ls -la' to run a command.\" },\n      press_enter: { type: \"boolean\", description: \"Whether to append a carriage return (Enter) after the input so the command or prompt answer is submitted. Defaults to true; set false to send raw input without submitting.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\",\n        additionalProperties: false,\n        properties: {\n          written: { type: \"integer\", required: true }\n        }\n      },\n      render(args, value) {\n        return [{ type: \"text\", text: `Sent ${value.written} bytes to the terminal session.` }];\n      }\n    },\n    async execute(args) {\n      let input = typeof args.input === \"string\" ? args.input : String(args.input ?? \"\");\n      // The physical Enter key emits a carriage return (\\\\r). Send that —\n      // not a bare \\\\n — so the input also submits to programs that put the\n      // terminal in raw mode (password prompts, [Y/n] confirmations).\n      if (args.press_enter !== false && !/[\\r\\n]$/.test(input)) input += \"\\r\";\n      // The input must land in a live terminal session. If the target\n      // connection has none open, open one first so \"write + enter\" actually\n      // executes instead of silently writing 0 bytes.\n      const ensure = await service.ensureSessionForWrite(args.connection_id);\n      if (!ensure.ok) throw new Error(`ssh_write failed: ${ensure.error.message}`);\n      const result = service.writeCurrentConnection({ connectionId: ensure.connectionId, input });\n      if (!result.ok) throw new Error(`ssh_write failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n\n  ctx.tools.register(defineTool({\n    name: \"ssh_disconnect\",\n    description: \"Close the current SSH connection and any open shell sessions on it. Omit connection_id for the current right-side SSH server.\",\n    parameters: {\n      connection_id: { type: \"string\", description: \"Optional. Omit to target the current right-side SSH connection.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\",\n        additionalProperties: false,\n        properties: {\n          disconnected: { type: \"boolean\", required: true }\n        }\n      },\n      render(args, value) {\n        return [{ type: \"text\", text: value.disconnected ? \"Disconnected.\" : \"Connection not found.\" }];\n      }\n    },\n    async execute(args) {\n      const result = await service.disconnectCurrentConnection({ connectionId: args.connection_id });\n      if (!result.ok) throw new Error(`ssh_disconnect failed: ${result.error.message}`);\n      return result.value;\n    }\n  }));\n}\n"
    },
    {
      "path": "src/trash.js",
      "content": "/**\n * Reversible deletion for agent-initiated file removal (ssh_exec, sftp_delete).\n *\n * When the safety gate blocks a *simple* `rm`/`unlink`/`rmdir` command, the\n * command is rewritten into a trash move: targets are moved into\n * `$HOME/.dsh-trash/` on the remote host and recorded in that directory's\n * `manifest.tsv` (trash name, original absolute path, epoch, ISO time). Every\n * trash run first purges manifest entries older than the retention window, so\n * expired copies disappear without ever installing a cron/at job on the\n * server. Restore is an ordinary `mv` of the manifest line back to the\n * recorded path.\n *\n * Only fully literal, single-command deletions are rewritten: anything with\n * pipelines, redirection, command substitution, globs, expansions, exotic\n * flags or unknown programs keeps the original operator-approval flow. The\n * generated script contains the word `rm` itself (the purge step), so it must\n * never be re-fed through assessShellCommand — callers rewrite before the\n * gate or keep the rewritten command inside the prepared-exec path.\n */\n\nexport const TRASH_DIR = \"$HOME/.dsh-trash\";\nexport const TRASH_MARKER = \"__DSH_TRASH_V1__\";\nexport const TRASH_RETENTION_MS = 24 * 60 * 60 * 1000;\nexport const TRASH_MANIFEST = \"manifest.tsv\";\n\nconst DELETE_PROGRAMS = new Set([\"rm\", \"unlink\", \"rmdir\"]);\n// Bundles of these short flags are understood; anything else (long options,\n// -p for rmdir, -i prompts whose semantics a move cannot reproduce) falls\n// back to the operator-approval path.\nconst RM_FLAGS = new Set([\"r\", \"R\", \"f\", \"v\", \"d\", \"i\"]);\nconst RMDIR_FLAGS = new Set([\"v\"]);\n// Characters that make a command line \"not a simple delete\": operators,\n// redirection, substitution, globs, brace/grouping syntax, comments. A path\n// containing a tab would also corrupt the TSV manifest.\nconst UNSAFE_CHARS = new Set([\";\", \"&\", \"|\", \"<\", \">\", \"`\", \"$\", \"*\", \"?\", \"[\", \"]\", \"(\", \")\", \"{\", \"}\", \"#\", \"\\t\", \"\\n\", \"\\r\"]);\n\n/**\n * Tokenize a command line the way a shell would for a purely literal command:\n * single-quoted (verbatim), double-quoted (escape-aware, expansion rejected)\n * and bare words. Each token records whether its first character came from\n * inside quotes, because tilde expansion only happens for an unquoted `~` —\n * `rm '~/x'` and `rm ~/x` mean different directories. Returns null whenever\n * anything ambiguous or dynamic is present — the caller then keeps the\n * conservative approval flow.\n */\nfunction tokenizeLiteralCommand(command) {\n  const tokens = [];\n  let current = \"\";\n  let hasToken = false;\n  let firstQuoted = false;\n  let i = 0;\n  const n = command.length;\n  const startToken = (fromQuote) => {\n    if (!hasToken) { hasToken = true; firstQuoted = fromQuote; }\n  };\n  const endToken = () => {\n    if (hasToken) { tokens.push({ text: current, quoted: firstQuoted }); current = \"\"; hasToken = false; }\n  };\n  while (i < n) {\n    const ch = command[i];\n    if (ch === \"'\") {\n      const end = command.indexOf(\"'\", i + 1);\n      if (end === -1) return null;\n      startToken(true);\n      current += command.slice(i + 1, end);\n      i = end + 1;\n      continue;\n    }\n    if (ch === '\"') {\n      let j = i + 1;\n      let part = \"\";\n      let closed = false;\n      while (j < n) {\n        const c = command[j];\n        if (c === \"\\\\\") {\n          const next = command[j + 1];\n          if (next === '\"' || next === \"\\\\\" || next === \"$\" || next === \"`\") { part += next; j += 2; continue; }\n          return null;\n        }\n        if (c === '\"') { closed = true; j++; break; }\n        if (c === \"$\" || c === \"`\") return null;\n        part += c;\n        j++;\n      }\n      if (!closed) return null;\n      startToken(true);\n      current += part;\n      i = j;\n      continue;\n    }\n    if (ch === \"\\\\\") {\n      const next = command[i + 1];\n      if (next === undefined || next === \"\\n\") return null;\n      startToken(false);\n      current += next;\n      i += 2;\n      continue;\n    }\n    if (ch === \" \" || ch === \"\\t\") {\n      endToken();\n      i++;\n      continue;\n    }\n    if (UNSAFE_CHARS.has(ch)) return null;\n    if (ch.charCodeAt(0) < 32 || ch.charCodeAt(0) === 127) return null;\n    startToken(false);\n    current += ch;\n    i++;\n  }\n  endToken();\n  return tokens;\n}\n\n/**\n * Parse an agent-issued command line as a simple, fully literal deletion.\n * Returns `{ targets }` (each `{ kind: \"plain\"|\"home\", path }`) when the whole\n * line is one rm/unlink/rmdir invocation with recognized flags and explicit\n * literal paths; null otherwise, meaning the caller must keep the\n * operator-approval flow.\n */\nexport function parseSimpleDeleteCommand(command) {\n  if (typeof command !== \"string\") return null;\n  const tokens = tokenizeLiteralCommand(command.trim());\n  if (tokens === null || tokens.length < 2) return null;\n  const program = tokens[0].text;\n  if (!DELETE_PROGRAMS.has(program)) return null;\n\n  const targets = [];\n  let noMoreFlags = false;\n  for (let i = 1; i < tokens.length; i++) {\n    const token = tokens[i].text;\n    if (!noMoreFlags && token === \"--\") { noMoreFlags = true; continue; }\n    if (!noMoreFlags && token.startsWith(\"-\") && token.length > 1) {\n      if (token.startsWith(\"--\")) return null; // long options → card\n      for (const flag of token.slice(1)) {\n        const allowed = program === \"rmdir\" ? RMDIR_FLAGS : RM_FLAGS;\n        if (!allowed.has(flag)) return null;\n      }\n      continue;\n    }\n    // A lone \"-\" is a stdin convention, not a path we can move.\n    if (token === \"-\" || token.length === 0) return null;\n    // A tab/newline inside a quoted path would corrupt the TSV manifest —\n    // such targets keep the operator-approval flow instead.\n    if (/[\\t\\n\\r\\0]/.test(token)) return null;\n    if (token === \"/\" || token === \".\" || token === \"..\") return null;\n    if (token.startsWith(\"~\")) {\n      if (tokens[i].quoted) {\n        // A quoted `~` is a literal directory name for the shell too, so the\n        // move must keep it verbatim — identical to what rm would remove.\n        targets.push({ kind: \"plain\", path: token });\n      } else if (token === \"~\" || !token.startsWith(\"~/\")) {\n        return null; // bare ~ or ~user paths: refuse / cannot resolve\n      } else if (token.length === 2) {\n        return null; // bare ~/\n      } else {\n        targets.push({ kind: \"home\", path: token.slice(2) });\n      }\n    } else {\n      targets.push({ kind: \"plain\", path: token });\n    }\n  }\n  if (targets.length === 0) return null;\n  return { program, targets };\n}\n\nfunction quoteTarget(target) {\n  if (target.kind === \"home\") {\n    // The tokenizer guarantees no \" $ ` \\ survive inside a target, so the\n    // expansion is the only dynamic part and it is safe inside double quotes.\n    return `\"$HOME/${target.path}\"`;\n  }\n  return shellSingleQuote(target.path);\n}\n\n/**\n * Build the remote POSIX-shell script that implements the trash move for the\n * parsed targets. The script:\n *   1. creates `$HOME/.dsh-trash/`,\n *   2. purges manifest entries older than `retentionMs` (no cron/at needed),\n *   3. moves each existing target into the trash under `<epoch>-<basename>`,\n *   4. appends a manifest line (name, original absolute path, epoch, ISO time),\n *   5. reports one `__DSH_TRASH_V1__` line per target for host-side parsing.\n * All paths are quoted; busybox/GNU/macOS coreutils all cover the used\n * builtins (mkdir/mv/awk/date/printf). The script always exits 0 — failures\n * are reported per target, never thrown.\n */\nexport function buildTrashCommand(targets, { retentionMs = TRASH_RETENTION_MS } = {}) {\n  const retentionSec = Math.max(1, Math.floor(retentionMs / 1000));\n  const list = targets.map(quoteTarget).join(\" \");\n  return [\n    '__dsh_t=\"$HOME/.dsh-trash\"',\n    'mkdir -p \"$__dsh_t\" || { printf \\'__DSH_TRASH_V1__\\\\terror\\\\ttrash-dir\\\\n\\'; exit 0; }',\n    \"__dsh_n=$(date +%s)\",\n    '__dsh_m=\"$__dsh_t/manifest.tsv\"',\n    \"if [ -f \\\"$__dsh_m\\\" ]; then\",\n    `  __dsh_cut=$((__dsh_n - ${retentionSec}))`,\n    '  __dsh_tmp=\"$__dsh_t/.purge.$$\"',\n    \"  awk -F'\\\\t' -v c=\\\"$__dsh_cut\\\" '$3+0 > 0 && $3+0 < c { print $1 }' \\\"$__dsh_m\\\" > \\\"$__dsh_tmp\\\" 2>/dev/null || : > \\\"$__dsh_tmp\\\"\",\n    '  __dsh_purged=0',\n    '  while IFS= read -r __dsh_x; do',\n    '    case \"$__dsh_x\" in \"\"|\".\"|\"..\"|*/*) continue ;; esac',\n    '    if rm -rf \"$__dsh_t/$__dsh_x\"; then __dsh_purged=$((__dsh_purged + 1)); fi',\n    '  done < \"$__dsh_tmp\"',\n    '  if [ \"$__dsh_purged\" -gt 0 ]; then',\n    \"    awk -F'\\\\t' -v c=\\\"$__dsh_cut\\\" '!($3+0 > 0 && $3+0 < c)' \\\"$__dsh_m\\\" > \\\"$__dsh_tmp\\\" 2>/dev/null && cat \\\"$__dsh_tmp\\\" > \\\"$__dsh_m\\\"\",\n    '  fi',\n    '  rm -f \"$__dsh_tmp\"',\n    `  printf '${TRASH_MARKER}\\\\tpurged\\\\t%d\\\\n' \"$__dsh_purged\"`,\n    \"fi\",\n    \"__dsh_i=0\",\n    `for __dsh_p in ${list}; do`,\n    '  case \"$__dsh_p\" in /*) : ;; *) __dsh_p=\"./$__dsh_p\" ;; esac',\n    '  __dsh_q=$__dsh_p',\n    '  while : ; do case \"$__dsh_q\" in */) __dsh_q=\"${__dsh_q%/}\" ;; *) break ;; esac; done',\n    '  case \"$__dsh_q\" in /*) __dsh_abs=$__dsh_q ;; *) __dsh_abs=\"$(pwd -P 2>/dev/null || pwd)/${__dsh_q#./}\" ;; esac',\n    '  if [ ! -e \"$__dsh_q\" ] && [ ! -L \"$__dsh_q\" ]; then',\n    `    printf '${TRASH_MARKER}\\\\tmissing\\\\t%s\\\\n' \"$__dsh_abs\"`,\n    '    continue',\n    '  fi',\n    '  __dsh_b=${__dsh_q##*/}',\n    '  __dsh_name=\"$__dsh_n-$__dsh_b\"',\n    '  __dsh_d=\"$__dsh_t/$__dsh_name\"',\n    '  while [ -e \"$__dsh_d\" ] || [ -L \"$__dsh_d\" ]; do',\n    '    __dsh_i=$((__dsh_i + 1))',\n    '    __dsh_name=\"$__dsh_n-$__dsh_i-$__dsh_b\"',\n    '    __dsh_d=\"$__dsh_t/$__dsh_name\"',\n    '  done',\n    '  if mv \"$__dsh_q\" \"$__dsh_d\"; then',\n    '    printf \\'%s\\\\t%s\\\\t%s\\\\t%s\\\\n\\' \"$__dsh_name\" \"$__dsh_abs\" \"$__dsh_n\" \"$(date -u +%Y%m%dT%H%M%SZ)\" >> \"$__dsh_m\"',\n    `    printf '${TRASH_MARKER}\\\\tmoved\\\\t%s\\\\t%s\\\\n' \"$__dsh_abs\" \"$__dsh_d\"`,\n    '  else',\n    `    printf '${TRASH_MARKER}\\\\tfailed\\\\t%s\\\\n' \"$__dsh_abs\"`,\n    '  fi',\n    'done',\n    'exit 0'\n  ].join(\"\\n\");\n}\n\n/**\n * Extract the per-target report lines from a trash run's stdout and strip\n * them so neither the tool result nor the terminal mirror shows the protocol\n * lines. Returns `{ events, stdout }` with events like\n * `{ event: \"moved\", original, trashPath }`, `{ event: \"missing\"|\"failed\", original }`\n * and a single `{ event: \"purged\", count }`.\n */\nexport function parseTrashOutput(stdout) {\n  const events = [];\n  const kept = [];\n  for (const line of String(stdout ?? \"\").split(\"\\n\")) {\n    if (!line.startsWith(TRASH_MARKER)) { kept.push(line); continue; }\n    const parts = line.split(\"\\t\");\n    if (parts[1] === \"moved\" && parts.length >= 4) {\n      events.push({ event: \"moved\", original: parts[2], trashPath: parts[3] });\n    } else if ((parts[1] === \"missing\" || parts[1] === \"failed\" || parts[1] === \"error\") && parts.length >= 3) {\n      events.push({ event: parts[1], original: parts[2] });\n    } else if (parts[1] === \"purged\" && parts.length >= 3) {\n      events.push({ event: \"purged\", count: Number(parts[2]) || 0 });\n    }\n  }\n  return { events, stdout: kept.join(\"\\n\") };\n}\n\n/**\n * Parse a manifest.tsv body. Malformed lines are skipped; each entry keeps\n * its raw line because restore/purge rewrite the file by exact-line match.\n */\nexport function parseTrashManifest(text) {\n  const entries = [];\n  for (const raw of String(text ?? \"\").split(\"\\n\")) {\n    if (raw.length === 0) continue;\n    const parts = raw.split(\"\\t\");\n    if (parts.length < 4 || parts[0].length === 0 || parts[1].length === 0) continue;\n    const epoch = Number(parts[2]);\n    if (!Number.isFinite(epoch) || epoch <= 0) continue;\n    if (parts[0].includes(\"/\") || parts[0] === \".\" || parts[0] === \"..\") continue;\n    entries.push({ name: parts[0], original: parts[1], epoch, iso: parts[3], raw });\n  }\n  return entries;\n}\n\nfunction shellSingleQuote(text) {\n  return `'${String(text).replace(/'/g, \"'\\\\''\")}'`;\n}\n\nfunction manifestFilterCommand(entry) {\n  // Exact-line removal keeps every other entry byte-for-byte intact.\n  return `grep -v -F -x -- ${shellSingleQuote(entry.raw)}`;\n}\n\n/**\n * Build a remote script that moves one trash entry back to its recorded\n * original path (never overwriting an existing file) and drops the manifest\n * line. `entry` comes from parseTrashManifest.\n */\nexport function buildRestoreCommand(entry) {\n  if (!entry || typeof entry.name !== \"string\" || typeof entry.original !== \"string\") return null;\n  const parent = entry.original.replace(/\\/+[^/]*$/, \"\") || \"/\";\n  return [\n    `__dsh_f=\"$HOME/.dsh-trash/\"${shellSingleQuote(entry.name)}`,\n    'if [ ! -e \"$__dsh_f\" ] && [ ! -L \"$__dsh_f\" ]; then echo \"trash entry not found: $__dsh_f\" >&2; exit 1; fi',\n    `if [ -e ${shellSingleQuote(entry.original)} ] || [ -L ${shellSingleQuote(entry.original)} ]; then echo \"restore target already exists: ${entry.original.replace(/'/g, \"'\\\\''\")}\" >&2; exit 1; fi`,\n    `mkdir -p ${shellSingleQuote(parent)} || exit 1`,\n    `if mv \"$__dsh_f\" ${shellSingleQuote(entry.original)}; then`,\n    `  __dsh_m=\"$HOME/.dsh-trash/\"${shellSingleQuote(TRASH_MANIFEST)}`,\n    // grep -v exits 1 when it selects nothing (last line removed), so the\n    // rewrite must not hang off its exit status — an empty result is valid.\n    '  if [ -f \"$__dsh_m\" ]; then ' + manifestFilterCommand(entry) + ' \"$__dsh_m\" > \"$__dsh_m.r\" 2>/dev/null; cat \"$__dsh_m.r\" > \"$__dsh_m\" 2>/dev/null; rm -f \"$__dsh_m.r\"; fi',\n    '  echo restored',\n    'else',\n    '  echo \"restore move failed\" >&2',\n    '  exit 1',\n    'fi'\n  ].join(\"\\n\");\n}\n\n/**\n * Build a remote script that permanently deletes the given trash entries and\n * rewrites the manifest without them. This is the one place where a real\n * `rm -rf` is acceptable: it only ever touches paths inside the trash.\n */\nexport function buildPurgeCommand(entries) {\n  if (!Array.isArray(entries) || entries.length === 0) return null;\n  const lines = [\n    `__dsh_m=\"$HOME/.dsh-trash/\"${shellSingleQuote(TRASH_MANIFEST)}`\n  ];\n  for (const entry of entries) {\n    if (!entry || typeof entry.name !== \"string\" || entry.name.includes(\"/\") || entry.name === \".\" || entry.name === \"..\") continue;\n    lines.push(`if rm -rf \"$HOME/.dsh-trash/\"${shellSingleQuote(entry.name)}; then echo purged; fi`);\n    if (typeof entry.raw === \"string\" && entry.raw.length > 0) {\n      // grep -v exits 1 when it selects nothing (last line removed); the\n      // rewrite must still happen, so no && chaining here either.\n      lines.push(`if [ -f \"$__dsh_m\" ]; then ` + manifestFilterCommand(entry) + ` \"$__dsh_m\" > \"$__dsh_m.p\" 2>/dev/null; cat \"$__dsh_m.p\" > \"$__dsh_m\" 2>/dev/null; rm -f \"$__dsh_m.p\"; fi`);\n    }\n  }\n  return lines.join(\"\\n\");\n}\n"
    }
